def _event_image_is_discord_attachment(url: str) -> bool:
    value = str(url or "").strip()
    try:
        parsed = urllib.parse.urlparse(value)
        host = (parsed.hostname or "").lower()
        path = (parsed.path or "").lower()
    except Exception:
        return False
    return host in {
        "cdn.discordapp.com",
        "media.discordapp.net",
        "images-ext-1.discordapp.net",
        "images-ext-2.discordapp.net",
    } and ("/attachments/" in path or "/ephemeral-attachments/" in path)


def _stable_event_external_url(url: str) -> str:
    value = str(url or "").strip()
    if not value.startswith(("https://", "http://")):
        return ""
    # Discord-Anhangslinks können die signierten Query-Parameter benötigen.
    # Eigene URLs bleiben deshalb unverändert.
    return value


def _event_image_mode(ev: dict[str, Any]) -> str:
    return str(ev.get("image_type") or ev.get("image_preset") or "").strip().casefold()


def _event_image_preset_key(ev: dict[str, Any]) -> str:
    mode = _event_image_mode(ev)
    selected = _EVENT_IMAGE_PRESET_ALIASES.get(mode, mode if mode in _EVENT_IMAGE_ASSETS else "")
    if selected:
        return selected

    values = []
    for key in ("dkp_event_type", "event_type", "title", "name", "description"):
        value = ev.get(key)
        if value is not None:
            values.append(str(value))
    text = " ".join(values).casefold().replace("-", " ").replace("_", " ")
    if any(term in text for term in ("segensstein", "boonstone", "pvp")):
        return "pvp"
    if any(term in text for term in ("trial", "dimensionsprüfung", "dimensionspruefung", "prüfung", "pruefung")):
        return "trials"
    if any(term in text for term in ("hardmode", "hard mode", "hard raid", "hm raid")):
        return "hard_raid"
    if any(term in text for term in ("gildenboss", "gildenbosse", "guild boss", "guildboss")):
        return "guild_boss"
    if any(term in text for term in ("normalmodus", "normal mode", "normal raid", "nm raid")):
        return "normal_raid"
    return ""


def _event_image_raw_url(ev: dict[str, Any]) -> str:
    for key in ("image_url", "banner_url", "thumbnail_url", "media_url", "event_image_url"):
        value = str(ev.get(key) or "").strip()
        if value:
            return value
    embed = ev.get("embed") if isinstance(ev.get("embed"), dict) else {}
    for key in ("image_url", "thumbnail_url", "image", "thumbnail"):
        value = embed.get(key)
        if isinstance(value, dict):
            value = value.get("url")
        value = str(value or "").strip()
        if value:
            return value
    return ""


@app.get("/event-image/{preset_key}", include_in_schema=False)
def event_image_asset(preset_key: str):
    key = _EVENT_IMAGE_PRESET_ALIASES.get(str(preset_key or "").strip().casefold(), str(preset_key or "").strip().casefold())
    filename = _EVENT_IMAGE_FILES.get(key)
    if not filename:
        raise HTTPException(status_code=404, detail="Unbekanntes Eventbild")
    path = STATIC_DIR / "event_images" / filename
    if not path.is_file():
        raise HTTPException(status_code=404, detail="Eventbild fehlt im Deployment")
    return FileResponse(
        str(path),
        media_type="image/webp",
        headers={"Cache-Control": "public, max-age=86400, immutable"},
    )


def _dashboard_event_image_url(ev: dict[str, Any]) -> str:
    """Liefert für bekannte Eventtypen immer das feste lokale Bild.

    Das repariert auch bereits laufende Events, deren alte externe Bild-URL noch
    im Snapshot steht, aber inzwischen abgelaufen oder nicht mehr erreichbar ist.
    Nur ausdrücklich als eigene URL markierte Bilder bleiben extern.
    """
    raw = _event_image_raw_url(ev)
    mode = _event_image_mode(ev)

    if mode in _EVENT_IMAGE_NO_IMAGE_KEYS:
        return ""

    legacy = ""
    for marker, preset_key in _EVENT_IMAGE_LEGACY_MARKERS.items():
        if marker in raw:
            legacy = preset_key
            break

    # Früher wurden auch die fünf Standardbilder als "custom" gespeichert.
    # Solche bekannten alten Discord-Links werden auf das lokale Bild repariert.
    if mode in _EVENT_IMAGE_CUSTOM_KEYS and not legacy:
        return _stable_event_external_url(raw)

    # Bekannte Eventtypen verwenden immer das lokale, mitdeployte Standardbild.
    # Nur eine ausdrücklich gewählte eigene URL darf diese Zuordnung ersetzen.
    inferred = _event_image_preset_key(ev)
    preset_key = inferred or legacy
    if preset_key:
        return _EVENT_IMAGE_ASSETS.get(preset_key, "")

    # Unbekannte/benutzerdefinierte Alt-Events dürfen ihre externe URL behalten.
    if not mode and raw:
        return _stable_event_external_url(raw)

    if raw.startswith("/event-image/"):
        path = raw.split("?", 1)[0]
        return f"{path}?v={ASSET_VER}"
    if raw.startswith("/static/event_images/"):
        filename = raw.split("?", 1)[0].rsplit("/", 1)[-1]
        key = next((k for k, v in _EVENT_IMAGE_FILES.items() if v == filename), "")
        return _EVENT_IMAGE_ASSETS.get(key, "")
    if raw.startswith("/static/"):
        return raw

    if raw.startswith(("https://", "http://")):
        try:
            parsed = urllib.parse.urlsplit(raw)
            if parsed.path.startswith("/event-image/"):
                return f"{parsed.path}?v={ASSET_VER}"
            if parsed.path.startswith("/static/event_images/"):
                filename = parsed.path.rsplit("/", 1)[-1]
                key = next((k for k, v in _EVENT_IMAGE_FILES.items() if v == filename), "")
                return _EVENT_IMAGE_ASSETS.get(key, "")
        except Exception:
            pass
        return _stable_event_external_url(raw)
    return ""


def _database_url() -> str:
    return str(os.getenv("DATABASE_URL") or "").strip()


def _normalized_database_url() -> str:
    url = _database_url()
    if url.startswith("postgres://"):
        return "postgresql://" + url[len("postgres://"):]
    return url


def _pg_connect():
    import psycopg  # type: ignore
    from psycopg.rows import dict_row  # type: ignore

    return psycopg.connect(_normalized_database_url(), row_factory=dict_row, connect_timeout=10)


def _ensure_guild_profile_schema() -> None:
    if not _database_url():
        return
    conn = _pg_connect()
    try:
        with conn.cursor() as cur:
            cur.execute("""
                CREATE TABLE IF NOT EXISTS guild_profiles (
                    guild_id BIGINT PRIMARY KEY,
                    discord_name TEXT NOT NULL DEFAULT '',
                    display_name TEXT NOT NULL DEFAULT '',
                    short_name TEXT NOT NULL DEFAULT '',
                    bot_display_name TEXT NOT NULL DEFAULT '',
                    timezone_name TEXT NOT NULL DEFAULT 'Europe/Berlin',
                    logo_url TEXT NOT NULL DEFAULT '',
                    banner_url TEXT NOT NULL DEFAULT '',
                    accent_color TEXT NOT NULL DEFAULT '#d6a84f',
                    invite_url TEXT NOT NULL DEFAULT '',
                    status TEXT NOT NULL DEFAULT 'active',
                    previous_guild_id BIGINT,
                    created_at TEXT NOT NULL,
                    updated_at TEXT NOT NULL
                )
            """)
            cur.execute("""
                CREATE TABLE IF NOT EXISTS guild_settings (
                    guild_id BIGINT NOT NULL,
                    key TEXT NOT NULL,
                    value_json TEXT NOT NULL,
                    updated_at TEXT NOT NULL,
                    PRIMARY KEY (guild_id, key)
                )
            """)
            cur.execute("""
                CREATE TABLE IF NOT EXISTS module_settings (
                    guild_id BIGINT NOT NULL,
                    module TEXT NOT NULL,
                    key TEXT NOT NULL,
                    value_json TEXT NOT NULL,
                    updated_at TEXT NOT NULL,
                    PRIMARY KEY (guild_id, module, key)
                )
            """)
            cur.execute("CREATE INDEX IF NOT EXISTS idx_guild_profiles_status ON guild_profiles(status, updated_at DESC)")
        conn.commit()
    finally:
        conn.close()


def _guild_profile_row(guild_id: int) -> dict[str, Any]:
    if not _database_url() or not int(guild_id or 0):
        return {}
    try:
        _ensure_guild_profile_schema()
        conn = _pg_connect()
        try:
            with conn.cursor() as cur:
                cur.execute("SELECT * FROM guild_profiles WHERE guild_id=%s", (int(guild_id),))
                row = cur.fetchone()
                return dict(row) if row else {}
        finally:
            conn.close()
    except Exception:
        return {}


def _active_guild_id() -> int:
    # Ein explizit gesetztes DASHBOARD_GUILD_ID bindet diesen Web-Service
    # immer an genau diese Discord-Gilde. Das ist besonders wichtig, wenn
    # dieselbe Postgres-Datenbank noch Snapshots/Profiles anderer Gilden
    # enthält. Ohne diese Priorität konnte das Dashboard nach einem Guild-
    # Wechsel versehentlich Branding, Rollen und Auth-Listen der zuletzt
    # aktiven alten Gilde verwenden.
    explicit = str(os.getenv("DASHBOARD_GUILD_ID") or "").strip()
    if explicit.isdigit():
        return int(explicit)
    if not _database_url():
        return 0
    try:
        _ensure_guild_profile_schema()
        conn = _pg_connect()
        try:
            with conn.cursor() as cur:
                cur.execute("""
                    SELECT gp.guild_id
                    FROM guild_profiles gp
                    WHERE gp.status='active'
                      AND EXISTS (SELECT 1 FROM dashboard_snapshots ds WHERE ds.guild_id=gp.guild_id)
                    ORDER BY gp.updated_at DESC, gp.guild_id DESC
                    LIMIT 1
                """)
                row = cur.fetchone()
                if row:
                    return int(row.get("guild_id") or 0)
                cur.execute("SELECT guild_id FROM dashboard_snapshots ORDER BY published_at DESC, id DESC LIMIT 1")
                row = cur.fetchone()
                return int((row or {}).get("guild_id") or 0)
        finally:
            conn.close()
    except Exception:
        return 0


def _guild_setting_value(guild_id: int, key: str, default: Any = None) -> Any:
    if not _database_url() or not guild_id:
        return default
    try:
        _ensure_guild_profile_schema()
        conn = _pg_connect()
        try:
            with conn.cursor() as cur:
                cur.execute("SELECT value_json FROM guild_settings WHERE guild_id=%s AND key=%s", (int(guild_id), str(key)))
                row = cur.fetchone()
            if not row:
                return default
            return json.loads(row.get("value_json") or "null")
        finally:
            conn.close()
    except Exception:
        return default


def _set_guild_setting_value(guild_id: int, key: str, value: Any) -> None:
    _ensure_guild_profile_schema()
    conn = _pg_connect()
    try:
        with conn.cursor() as cur:
            cur.execute("""
                INSERT INTO guild_settings(guild_id,key,value_json,updated_at)
                VALUES (%s,%s,%s,%s)
                ON CONFLICT(guild_id,key) DO UPDATE SET value_json=EXCLUDED.value_json, updated_at=EXCLUDED.updated_at
            """, (int(guild_id), str(key), json.dumps(value, ensure_ascii=False, separators=(",", ":")), datetime.now(timezone.utc).isoformat()))
        conn.commit()
    finally:
        conn.close()


