def _event_by_id(snap: dict[str, Any], event_id: str) -> Optional[dict[str, Any]]:
    """Event suchen – inklusive direkter Eventliste, RSVP-Fallback und offener EC-Checks.

    Alte Versionen haben nur _events_with_pending_ec_checks() durchsucht. Dadurch
    konnten abgeschlossene/alte Events in der Anwesenheit leer erscheinen, obwohl
    die RSVP-Daten in Postgres noch vorhanden waren.
    """
    target = str(event_id or "").strip()
    if not target:
        return None

    # 1) Direkte Eventliste aus Snapshot/Postgres-Read-Cutover.
    events_obj = snap.get("events") if isinstance(snap.get("events"), dict) else {}
    for ev in events_obj.get("items") or []:
        if not isinstance(ev, dict):
            continue
        if str(ev.get("event_id") or ev.get("id") or "").strip() == target:
            return ev

    # 2) Eventliste plus EC-/Review-Fallbacks.
    for ev in _events_with_pending_ec_checks(snap):
        if isinstance(ev, dict) and str(ev.get("event_id") or ev.get("id") or "").strip() == target:
            return ev

    # 3) Minimal-Event direkt aus RSVP-Zeilen bauen. Reicht für Attendance.
    rsvp_items = ((snap.get("event_rsvps") or {}).get("items") or []) if isinstance(snap.get("event_rsvps"), dict) else []
    hits = [r for r in rsvp_items if isinstance(r, dict) and str(r.get("event_id") or "").strip() == target]
    if hits:
        title = str(hits[0].get("event_title") or hits[0].get("title") or f"Event {target}")
        ev = {"event_id": target, "id": target, "title": title, "source": "event_rsvps_fallback", "participants": {"yes": [], "maybe": [], "no": []}}
        yes_groups: dict[str, list[dict[str, Any]]] = {}
        for r in hits:
            uid = _user_id(r.get("user_id") or r.get("id"))
            person = {**r, "user_id": uid, "id": uid, "display_name": r.get("display_name") or r.get("name") or (f"User {uid}" if uid else "Unbekannt")}
            response = str(r.get("response") or r.get("status") or "").strip().lower()
            role = str(r.get("role_name") or r.get("role") or "Zusage").strip()
            role_l = role.lower()
            if response in {"no", "nein", "absent", "abgemeldet", "declined", "deny"} or role_l in {"no", "nein", "abgemeldet"} or "abmeld" in response:
                ev["participants"]["no"].append(person)
            elif response in {"maybe", "vielleicht", "tentative", "unsure"} or role_l in {"maybe", "vielleicht"}:
                ev["participants"]["maybe"].append(person)
            else:
                yes_groups.setdefault(role or "Zusage", []).append(person)
        ev["participants"]["yes"] = [{"role": role, "participants": people} for role, people in sorted(yes_groups.items())]
        ev["participant_count"] = sum(len(g.get("participants") or []) for g in ev["participants"]["yes"])
        ev["maybe_count"] = len(ev["participants"].get("maybe") or [])
        ev["no_count"] = len(ev["participants"].get("no") or [])
        ev["rsvp_count"] = len(hits)
        return ev
    return None


def _participant_rows(people: Any) -> list[list[Any]]:
    rows: list[list[Any]] = []
    for p in people or []:
        if not isinstance(p, dict):
            continue
        rows.append([_member_link(p.get("user_id"), p.get("display_name")), "ja" if p.get("is_dashboard_member") else "nein"])
    return rows


def _event_yes_groups(event: dict[str, Any]) -> list[dict[str, Any]]:
    participants = event.get("participants") if isinstance(event.get("participants"), dict) else {}
    groups = [x for x in (participants.get("yes") or []) if isinstance(x, dict)]
    if groups:
        return groups
    raw_yes = event.get("yes")
    out: list[dict[str, Any]] = []
    if isinstance(raw_yes, dict):
        for role, people in raw_yes.items():
            out.append({"role": str(role or "Zusage"), "participants": [x for x in (people or []) if isinstance(x, dict)]})
    elif isinstance(raw_yes, list):
        for row in raw_yes:
            if not isinstance(row, dict):
                continue
            if "participants" in row:
                out.append(row)
            else:
                role = str(row.get("role_name") or row.get("role") or "Zusage")
                found = next((g for g in out if str(g.get("role")) == role), None)
                if found is None:
                    found = {"role": role, "participants": []}
                    out.append(found)
                found["participants"].append(row)
    return out


def _event_current_member_map(snap: dict[str, Any]) -> dict[int, str]:
    """Aktuelle Gildenmitglieder aus Postgres und Snapshot-Fallback vereinigen."""
    out: dict[int, str] = {}
    sources = [
        snap.get("profiles"), snap.get("members"),
        snap.get("profiles_snapshot_fallback"), snap.get("members_snapshot_fallback"),
    ]
    for obj in sources:
        if not isinstance(obj, dict):
            continue
        rows = obj.get("items") or obj.get("profiles") or []
        if isinstance(rows, dict):
            rows = list(rows.values())
        for row in rows or []:
            if not isinstance(row, dict):
                continue
            uid = _user_id(row.get("user_id") or row.get("member_id") or row.get("discord_id") or row.get("id"))
            if not uid:
                continue
            name = str(row.get("display_name") or row.get("server_name") or row.get("discord_name") or row.get("ingame_name") or f"User {uid}").strip()
            if uid not in out or str(out[uid]).startswith("User "):
                out[uid] = name or f"User {uid}"
    return out


def _event_response_summary(snap: dict[str, Any], event: dict[str, Any]) -> dict[str, Any]:
    groups = _event_yes_groups(event)
    yes_people: list[dict[str, Any]] = []
    yes_ids: set[int] = set()
    for group in groups:
        for person in group.get("participants") or []:
            if not isinstance(person, dict):
                continue
            yes_people.append(person)
            uid = _user_id(person.get("user_id") or person.get("id"))
            if uid:
                yes_ids.add(uid)

    participants = event.get("participants") if isinstance(event.get("participants"), dict) else {}
    maybe_people = [x for x in (participants.get("maybe") or event.get("maybe") or []) if isinstance(x, dict)]
    no_people = [x for x in (participants.get("no") or event.get("no") or []) if isinstance(x, dict)]
    maybe_ids = {_user_id(x.get("user_id") or x.get("id")) for x in maybe_people}
    no_ids = {_user_id(x.get("user_id") or x.get("id")) for x in no_people}
    maybe_ids.discard(0)
    no_ids.discard(0)
    response_ids = yes_ids | maybe_ids | no_ids

    yes_count = sum(len(g.get("participants") or []) for g in groups)
    maybe_count = len(maybe_people)
    no_count = len(no_people)
    response_count = yes_count + maybe_count + no_count

    members = _event_current_member_map(snap)
    member_filter = (snap.get("guild") or {}).get("member_filter") if isinstance(snap.get("guild"), dict) else {}
    configured_total = int(_num((member_filter or {}).get("eligible_count"), 0)) if isinstance(member_filter, dict) else 0
    member_total = max(configured_total, len(members), response_count)
    no_response_ids = sorted(set(members) - response_ids, key=lambda uid: members.get(uid, f"User {uid}").casefold())
    no_response_count = max(0, member_total - response_count)
    vote_percent = round((response_count / member_total) * 100, 1) if member_total else 0.0
    return {
        "groups": groups,
        "yes_people": yes_people,
        "maybe_people": maybe_people,
        "no_people": no_people,
        "yes_count": yes_count,
        "maybe_count": maybe_count,
        "no_count": no_count,
        "response_count": response_count,
        "member_total": member_total,
        "vote_percent": vote_percent,
        "member_names": members,
        "no_response_ids": no_response_ids,
        "no_response_count": no_response_count,
    }


def _event_person_name(person: dict[str, Any]) -> str:
    uid = _user_id(person.get("user_id") or person.get("id"))
    return str(person.get("display_name") or person.get("name") or person.get("server_name") or (f"User {uid}" if uid else "Unbekannt"))


def _event_name_chips(items: list[tuple[str, str]], *, empty: str = "Keine") -> str:
    if not items:
        return f'<div class="empty">{_e(empty)}</div>'
    return '<div class="event-name-chips">' + ''.join(
        f'<span class="event-name-chip {(_e(kind))}"><b>{_e(name)}</b><small>{_e(label)}</small></span>'
        for name, kind, label in [(name, kind, {"maybe":"Vielleicht", "declined":"Abgemeldet", "missing":"Keine Rückmeldung"}.get(kind, kind)) for name, kind in items]
    ) + '</div>'


def _event_role_overview_html(event: dict[str, Any], guild_id: int = 0) -> str:
    groups = _event_yes_groups(event)
    if not groups:
        return '<div class="empty">Keine Zusagen vorhanden.</div>'
    participant_ids: list[int] = []
    for group in groups:
        for person in group.get("participants") or []:
            if isinstance(person, dict):
                uid = _user_id(person.get("user_id") or person.get("id"))
                if uid:
                    participant_ids.append(uid)
    profiles = _aion2_profiles_for_users(int(guild_id or 0), participant_ids) if guild_id else {}
    order = {"TANK": 0, "SUPPORT": 1, "HEAL": 1, "HEALER": 1, "DPS": 2, "BANK": 3, "RESERVE": 3}
    groups = sorted(groups, key=lambda g: (order.get(str(g.get("role") or "").upper(), 20), str(g.get("role") or "").casefold()))
    blocks: list[str] = []
    for group in groups:
        role_raw = str(group.get("role") or "Zusage")
        role_key = normalize_event_role(role_raw) or role_raw
        people = [x for x in (group.get("participants") or []) if isinstance(x, dict)]
        chips: list[str] = []
        for person in sorted(people, key=lambda p: _event_person_name(p).casefold()):
            uid = _user_id(person.get("user_id") or person.get("id"))
            ap = profiles.get(uid) or {}
            cls = _aion2_normalize_class(ap.get("class_name"))
            icon = _cell(_aion2_class_display_html(cls, with_name=False)) if cls else ""
            chips.append(f'<span class="event-role-name" title="{_e(cls or "Keine Aion-2-Klasse")}">{icon}<b>{_e(_event_person_name(person))}</b></span>')
        names_html = ''.join(chips) or '<span class="muted">Niemand</span>'
        blocks.append(f'<div class="event-role-card"><div class="event-role-head"><h3>{_cell(_aion2_role_icon_html(role_key, with_label=True))}</h3><span class="pill">{len(people)}</span></div><div class="event-role-names">{names_html}</div></div>')
    return '<div class="event-role-grid">' + ''.join(blocks) + '</div>'


def _role_signup_html(event: dict[str, Any]) -> str:
    parts = ((event.get("participants") or {}).get("yes") or [])
    if not parts:
        return "<div class='empty'>Keine Zusagen vorhanden.</div>"
    blocks: list[str] = []
    for group in parts:
        if not isinstance(group, dict):
            continue
        role = group.get("role") or "Unbekannt"
        people = group.get("participants") or []
        blocks.append(f"""
        <div class="subpanel">
          <h3>{_e(role)} <span class='pill'>{_e(len(people))}</span></h3>
          {_table(['Spieler','Gildenrolle'], _participant_rows(people), placeholder=f'{role} durchsuchen…')}
        </div>
        """)
    return "".join(blocks)


