def _need_builder_profile_redirect(
    request: Request,
    user_id: int,
    *,
    build_id: str = "",
    msg: str = "",
) -> str:
    params: dict[str, str] = {}
    me = _current_user_id(request)
    if _is_portal_admin(request) or int(user_id or 0) != int(me or 0):
        params["user_id"] = str(int(user_id))
    if build_id:
        params["build"] = str(build_id)
    if msg:
        params["msg"] = str(msg)
    return "/character-editor" + (("?" + urllib.parse.urlencode(params)) if params else "")

@app.get("/character-editor", response_class=HTMLResponse)
def character_editor_page(request: Request, msg: str = "", _: bool = Depends(_auth)):
    try:
        return HTMLResponse(_render_need_builder_dashboard(_snapshot_payload(), request, msg=msg, embedded=False))
    except Exception as exc:
        return HTMLResponse(
            _html_shell(
                "Charakter-Editor Fehler",
                f"<section class='panel'><h1>❌ Charakter-Editor Fehler</h1><p>{_e(type(exc).__name__)}: {_e(exc)}</p></section>",
                nav_mode="member",
            ),
            status_code=500,
        )


@app.get("/needs", response_class=HTMLResponse)
def needs_page(request: Request, msg: str = "", _: bool = Depends(_auth)):
    params: dict[str, str] = {}
    for key in ("user_id", "build"):
        value = str(request.query_params.get(key) or "").strip()
        if value:
            params[key] = value
    if msg:
        params["msg"] = msg
    url = "/character-editor" + (("?" + urllib.parse.urlencode(params)) if params else "")
    return RedirectResponse(url=url, status_code=303)


@app.post("/needs/builds/new")
async def need_build_new(request: Request, _: bool = Depends(_auth)):
    data = _snapshot_payload(); guild_id = _safe_guild_id(data)
    form = _parse_urlencoded_body(await request.body())
    user_id = _user_id(form.get("user_id")) or _current_user_id(request)
    if not _portal_can_view(request, int(user_id)) and not _is_portal_admin(request):
        raise HTTPException(status_code=403, detail="Keine Berechtigung für diese Needliste.")
    bid = _need_builder_create_default(int(guild_id), int(user_id))
    return RedirectResponse(url=_need_builder_profile_redirect(request, int(user_id), build_id=bid, msg="Build erstellt"), status_code=303)


@app.post("/needs/builds/save")
async def need_build_save(request: Request, _: bool = Depends(_auth)):
    data = _snapshot_payload(); guild_id = _safe_guild_id(data)
    form = _parse_urlencoded_body(await request.body())
    user_id = _user_id(form.get("user_id")) or _current_user_id(request)
    if not _portal_can_view(request, int(user_id)) and not _is_portal_admin(request):
        raise HTTPException(status_code=403, detail="Keine Berechtigung für diese Needliste.")
    slot_ids = {slot: _user_id(form.get(f"slot_{slot}")) for slot in _NEED_BUILDER_SLOTS}
