def _parse_urlencoded_body(raw: bytes) -> dict[str, str]:
    parsed = urllib.parse.parse_qs((raw or b"").decode("utf-8", errors="replace"), keep_blank_values=True)
    return {str(k): str(v[-1] if v else "") for k, v in parsed.items()}


# ---------------------------------------------------------------------------
# Schritt 3: Spieler- & Mitgliederportal / Need-Änderungen
# ---------------------------------------------------------------------------

def _is_portal_admin(request: Request) -> bool:
    if _is_dashboard_admin(request):
        return True
    if _auth_mode() in {"basic", "hybrid"} and not _discord_oauth_enabled():
        return True
    return False


def _nav_mode_for_request(request: Request) -> str:
    return "admin" if _is_portal_admin(request) else "member"


def _current_user_id(request: Request) -> int:
    user = _current_user(request) or {}
    return _user_id(user.get("user_id") or user.get("id"))


def _portal_can_view(request: Request, user_id: int) -> bool:
    uid = int(user_id or 0)
    me = _current_user_id(request)
    return bool(uid and (me == uid or _is_portal_admin(request)))


def _portal_user_name(request: Request) -> str:
    u = _current_user(request) or {}
    return str(u.get("username") or u.get("global_name") or u.get("user_id") or "Dashboard")


def _need_change_status_label(status: Any) -> dict[str, str]:
    s = str(status or "pending").lower()
    labels = {
        "pending": "⏳ offen",
        "processing": "⚙️ Verarbeitung",
        "done": "✅ erledigt",
        "failed": "❌ Fehler",
        "rejected": "⛔ blockiert",
        "cancelled": "🚫 abgebrochen",
    }
    cls = "pill"
    if s in {"failed", "rejected"}:
        cls += " bad"
    elif s == "done":
        cls += " ok"
    return _raw(f'<span class="{cls}">{_e(labels.get(s, s))}</span>')


def _need_change_requests(guild_id: int, *, user_id: int = 0, limit: int = 80) -> list[dict[str, Any]]:
    if not _database_url() or not guild_id:
        return []
    _ensure_admin_tables()
    conn = _pg_connect()
    try:
        with conn.cursor() as cur:
            if user_id:
                cur.execute(
                    """
                    SELECT id, request_id, guild_id, target_user_id, action_type, status, payload_json,
                           actor_id, actor_name, requested_at, claimed_at, processed_at, result_json
                    FROM dashboard_need_change_requests
                    WHERE guild_id = %s AND target_user_id = %s
                    ORDER BY requested_at DESC, id DESC
                    LIMIT %s
                    """,
                    (int(guild_id), int(user_id), int(limit)),
                )
            else:
                cur.execute(
                    """
                    SELECT id, request_id, guild_id, target_user_id, action_type, status, payload_json,
                           actor_id, actor_name, requested_at, claimed_at, processed_at, result_json
                    FROM dashboard_need_change_requests
                    WHERE guild_id = %s
                    ORDER BY requested_at DESC, id DESC
                    LIMIT %s
                    """,
                    (int(guild_id), int(limit)),
                )
            rows = []
            for r in (cur.fetchall() or []):
                d = dict(r)
                try:
                    d["payload"] = json.loads(d.get("payload_json") or "{}")
                except Exception:
                    d["payload"] = {}
                try:
                    d["result"] = json.loads(d.get("result_json") or "{}")
                except Exception:
                    d["result"] = {}
                rows.append(d)
            return rows
    finally:
        conn.close()


def _create_need_change_request(guild_id: int, target_user_id: int, action_type: str, payload: dict[str, Any], actor: dict[str, Any]) -> str:
    if not _database_url() or not guild_id:
        raise RuntimeError("DATABASE_URL fehlt. Need-Änderungen laufen über Postgres-Queue.")
    request_id = f"need_{int(time.time())}_{secrets.token_hex(5)}"
    actor_id = str(actor.get("user_id") or "")
    actor_name = str(actor.get("username") or actor.get("global_name") or actor_id or "Dashboard")
    _ensure_admin_tables()
    conn = _pg_connect()
    try:
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO dashboard_need_change_requests
                    (request_id, guild_id, target_user_id, action_type, status, payload_json, actor_id, actor_name)
                VALUES (%s, %s, %s, %s, 'pending', %s, %s, %s)
                """,
                (request_id, int(guild_id), int(target_user_id), str(action_type), json.dumps(payload, ensure_ascii=False), actor_id, actor_name),
            )
            cur.execute(
                """
                INSERT INTO dashboard_admin_action_log
                    (guild_id, action_type, target_type, target_id, actor_id, actor_name, payload_json)
                VALUES (%s, %s, %s, %s, %s, %s, %s)
                """,
                (int(guild_id), "need_change_request", "member", str(target_user_id), actor_id, actor_name, json.dumps({"request_id": request_id, "action_type": action_type, "slot": payload.get("slot"), "tab": payload.get("tab")}, ensure_ascii=False)),
            )
        conn.commit()
    finally:
        conn.close()
    return request_id


def _portal_active_events(snap: dict[str, Any], user_id: int = 0) -> list[dict[str, Any]]:
    events = []
    now = datetime.now(timezone.utc)
    for ev in ((snap.get("events") or {}).get("items") or []):
        if not isinstance(ev, dict):
            continue
        dt = _event_dt_obj(ev.get("when_iso") or ev.get("start_at"))
        if _is_running_event(ev) or (dt and dt >= now):
            events.append(ev)
    events.sort(key=lambda ev: _event_dt_obj(ev.get("when_iso") or ev.get("start_at")) or datetime.max.replace(tzinfo=BERLIN_TZ))
    return events[:40]


def _portal_event_status_for_user(ev: dict[str, Any], user_id: int) -> str:
    uid = int(user_id or 0)
    parts = ev.get("participants") or {}
    for group in parts.get("yes") or []:
        if isinstance(group, dict) and any(isinstance(p, dict) and _user_id(p.get("user_id")) == uid for p in group.get("participants") or []):
            return "✅ " + str(group.get("role") or "Zusage")
    if any(isinstance(p, dict) and _user_id(p.get("user_id")) == uid for p in parts.get("maybe") or []):
        return "🟡 Vielleicht"
    if any(isinstance(p, dict) and _user_id(p.get("user_id")) == uid for p in parts.get("no") or []):
        return "❌ Abgemeldet"
    return "—"


def _portal_active_auctions(snap: dict[str, Any]) -> list[dict[str, Any]]:
    try:
        return list((_loot_center_payload_from_snapshot(snap).get("active") or [])[:40])
    except Exception:
        return []


def _slot_options_html() -> str:
    return "".join(f'<option value="{_e(slot)}">{_e(slot)}</option>' for slot in _NEED_SLOTS)


def _weapon_type_options_html() -> str:
    return "".join(f'<option value="{_e(w)}">{_e(w)}</option>' for w in _WEAPON_TYPES)


def _render_need_editor_panel(
    user_id: int,
    current_user: Optional[dict[str, Any]],
    requests: list[dict[str, Any]],
    snap: Optional[dict[str, Any]] = None,
    *,
    compact: bool = False,
    item_catalog: Optional[list[dict[str, Any]]] = None,
) -> str:
    snap = snap or {}
    req_rows = []
    for r in requests[:30]:
        p = r.get("payload") if isinstance(r.get("payload"), dict) else {}
        res = r.get("result") if isinstance(r.get("result"), dict) else {}
        detail = res.get("message") or res.get("error") or p.get("item_name") or p.get("item_text") or p.get("item_id") or "—"
        req_rows.append([_dt(r.get("requested_at")), _need_change_status_label(r.get("status")), r.get("action_type"), p.get("tab"), p.get("slot"), _short(detail, 120)])

    need_info = _needs_by_user(snap).get(int(user_id), {})
    main_map = _need_slot_map((need_info or {}).get("main") or (need_info or {}).get("main_needs") or []) if isinstance(need_info, dict) else {}
    sec_map = _need_slot_map((need_info or {}).get("secondary") or (need_info or {}).get("secondary_needs") or (need_info or {}).get("second") or []) if isinstance(need_info, dict) else {}
    rich_items = item_catalog if item_catalog is not None else _need_builder_items()
    catalog_by_name = {_loot_key(it.get("name")): it for it in rich_items if _loot_key(it.get("name"))}

    def catalog_item_for_name(value: Any) -> dict[str, Any]:
        """Robuste Zuordnung alter Need-Texte zum zentralen Itemkatalog.

        Alte Snapshot-Einträge enthalten teilweise Waffenart, Slotpräfixe oder
        typografisch andere Apostrophe. Ohne diese Normalisierung hatten
        belegte Slots keine catalog_id und damit auch keinen Hover-Tooltip.
        """
        clean = _clean_item_display_name(value)
        key = _loot_key(clean)
        if not key:
            return {}
        exact = catalog_by_name.get(key)
        if exact:
            return exact
        compact = re.sub(r"[^a-z0-9äöüß]+", "", key)
        if not compact:
            return {}
        for item_key, item in catalog_by_name.items():
            item_compact = re.sub(r"[^a-z0-9äöüß]+", "", item_key)
            if item_compact == compact:
                return item
        # Letzter sicherer Fallback für ältere Bezeichnungen mit Zusatztext.
        matches = [item for item_key, item in catalog_by_name.items() if len(key) >= 8 and (key in item_key or item_key in key)]
        return matches[0] if len(matches) == 1 else {}

    slot_filters_json = json.dumps({slot: _need_builder_slot_filter(slot) for slot in _NEED_SLOTS}, ensure_ascii=False)

    slot_icons = {
        "Waffe 1": "⚔️", "Waffe 2": "🗡️", "Fähigkeitskern 1": "✨", "Fähigkeitskern 2": "🌟",
        "Helm": "🪖", "Brust": "🦺", "Hose": "👖", "Handschuhe": "🧤", "Schuhe": "🥾",
        "Umhang": "🧥", "Kette": "📿", "Armband": "🫳", "Brosche": "🎖️", "Ohrringe": "💠",
        "Ring 1": "💍", "Ring 2": "💍", "Gürtel": "🪢",
    }
    slot_areas = {
        "Helm": "head", "Kette": "neck", "Ohrringe": "ear", "Umhang": "cloak",
        "Waffe 1": "weapon1", "Waffe 2": "weapon2", "Brust": "chest", "Handschuhe": "hands",
        "Hose": "legs", "Schuhe": "feet", "Gürtel": "belt", "Armband": "bracelet",
        "Brosche": "brooch", "Ring 1": "ring1", "Ring 2": "ring2",
        "Fähigkeitskern 1": "core1", "Fähigkeitskern 2": "core2",
    }

    def item_model(entry: Any) -> tuple[str, str, str]:
        current = _need_item_display(entry) if entry else ""
        item = catalog_item_for_name(current) if current else {}
        image_url = str(item.get("image") or item.get("image_url") or "").strip() if isinstance(item, dict) else ""
        rarity = str(item.get("rarity") or "").strip() if isinstance(item, dict) else ""
        return current, image_url, rarity

    def preview_html(slot: str, current: str, image_url: str, *, large: bool = False) -> str:
        cls = "equipment-img large" if large else "equipment-img"
        if image_url:
            return f'<img class="{cls}" src="{_e(image_url)}" alt="{_e(current or slot)}" loading="lazy">'
        return f'<div class="equipment-placeholder{(" large" if large else "")}">{_e(slot_icons.get(slot, "🧩"))}</div>'

    def editor_html(tab: str, slot: str, entry: Any, idx: int) -> str:
        locked = bool(entry and _need_is_received(entry))
        current, image_url, rarity = item_model(entry)
        input_id = f"need-equipment-{int(user_id)}-{tab.lower()}-{idx}"
        slot_id = f"need-equipment-slot-{int(user_id)}-{tab.lower()}-{idx}"
        editor_id = f"need-equipment-editor-{tab.lower()}-{idx}"
        hidden_slot = f'<select id="{_e(slot_id)}" class="need-slot-select" name="slot" style="display:none"><option selected value="{_e(slot)}">{_e(slot)}</option></select>'
        image = preview_html(slot, current, image_url, large=True)
        if locked:
            return f"""
            <section class="equipment-editor" id="{_e(editor_id)}" data-tab="{_e(tab.lower())}" data-slot-name="{_e(slot)}" hidden>
              <div class="equipment-editor-preview">{image}</div>
              <div class="equipment-editor-main">
                <div class="equipment-editor-title"><div><span>{_e(slot)}</span><strong>{_e(current or '—')}</strong></div><span class="need-state locked">Erhalten</span></div>
                <p class="muted">Dieser Slot ist als erhalten markiert und bleibt gesperrt. Nur die Gildenleitung kann ihn wieder freigeben.</p>
              </div>
            </section>"""
        current_item = catalog_item_for_name(current) if current else {}
        current_id = int((current_item or {}).get("id") or 0)
        current_sub = str((current_item or {}).get("sub") or "")
        current_weapon = _weapon_type_from_text(f"{current_sub} {current}") if slot.startswith("Waffe") else ""
        weapon_picker = ""
        if slot.startswith("Waffe"):
            weapon_options = ['<option value="">Waffenart auswählen</option>']
            for weapon_type in _WEAPON_TYPES:
                selected_attr = " selected" if weapon_type == current_weapon else ""
                weapon_options.append(f'<option value="{_e(weapon_type)}"{selected_attr}>{_e(weapon_type)}</option>')
            weapon_picker = (
                '<label class="ne-weapon-label"><span>1. Waffenart</span>'
                f'<select name="weapon_type" class="ne-weapon-type" data-dirty-field="1">{"".join(weapon_options)}</select></label>'
            )
        picker_thumb = f'<img src="{_e(image_url)}" alt="" loading="lazy">' if image_url else f'<span>{_e(slot_icons.get(slot, "🧩"))}</span>'
        current_meta = " · ".join(x for x in [str((current_item or {}).get("rarity") or ""), str((current_item or {}).get("sub") or "")] if x) or "Passende Katalogeinträge"
        picker = f"""
        <div class="ne-picker-wrap" data-ne-slot="{_e(slot)}">
          {weapon_picker}
          <label class="ne-item-label"><span>{'2. Item' if slot.startswith('Waffe') else 'Item auswählen'}</span>
            <button type="button" class="ne-picker-button" data-ne-open-picker="1">
              <span class="ne-picker-thumb" data-ne-picker-thumb="1">{picker_thumb}</span>
              <span class="ne-picker-copy"><strong data-ne-picker-label="1">{_e(current or 'Item auswählen')}</strong><small data-ne-picker-meta="1">{_e(current_meta)}</small></span>
              <span class="ne-picker-arrow">⌄</span>
            </button>
          </label>
          <input id="{_e(input_id)}" type="hidden" name="item_text" value="{_e(current)}" data-ne-item-value="1" data-dirty-field="1" data-item-id="{current_id}" data-image="{_e(image_url)}" data-label="{_e(current)}">
        </div>
        """
        return f"""
        <form class="equipment-editor" id="{_e(editor_id)}" data-tab="{_e(tab.lower())}" data-live-preview="1" data-empty-icon="{_e(slot_icons.get(slot, '🧩'))}" data-slot-name="{_e(slot)}" hidden method="post" action="/portal/member/{int(user_id)}/need-change">
          <input type="hidden" name="action_type" value="set">
          <input type="hidden" name="tab" value="{_e(tab)}">
          {hidden_slot}
          <div class="equipment-editor-preview" data-preview-box="1">{image}</div>
          <div class="equipment-editor-main">
            <div class="equipment-editor-title"><div><span>{_e(slot)}</span><strong data-preview-label="1">{_e(current or 'Noch kein Item gewählt')}</strong></div><span class="need-state {('filled' if current else 'empty')}">{('Gesetzt' if current else 'Leer')}</span></div>
            <div class="equipment-editor-picker">{picker}</div>
            <div class="equipment-unsaved" data-unsaved-warning="1" hidden>⚠️ Ungespeicherte Änderung – bitte speichern oder bewusst verwerfen.</div>
            <div class="equipment-editor-actions">
              <button class="btn" type="submit">Speichern &amp; an Bot senden</button>
              <button class="btn ghost" type="submit" name="action_type" value="clear" onclick="return confirm('Need für {_e(slot)} entfernen?')">Slot leeren</button>
            </div>
            <small class="muted">{_e(rarity or 'Item-Datenbank')} · Bilder und Werte stammen aus derselben Item-Datenbank wie im Charakter-Builder.</small>
          </div>
        </form>"""

    def board_html(tab: str, slot_map: dict[str, Any]) -> str:
        upper_cards: list[str] = []
        lower_cards: list[str] = []
        editors: list[str] = []
        upper_slots = {"Helm", "Waffe 1", "Waffe 2", "Brust", "Hose", "Handschuhe", "Schuhe", "Umhang", "Gürtel"}
        idx = 0
        for _, slots in _NEED_SLOT_GROUPS:
            for slot in slots:
                idx += 1
                current, image_url, rarity = item_model(slot_map.get(slot))
                current_item = catalog_item_for_name(current) if current else {}
                current_item_id = int((current_item or {}).get("id") or 0)
                editor_id = f"need-equipment-editor-{tab.lower()}-{idx}"
                area = slot_areas.get(slot, "auto")
                locked = bool(slot_map.get(slot) and _need_is_received(slot_map.get(slot)))
                state_cls = "locked" if locked else ("filled" if current else "empty")
                state_txt = "🔒" if locked else ("✓" if current else "+")
                card = f"""
                <button type="button" class="equipment-slot {state_cls}" style="grid-area:{_e(area)}" data-open-equipment="{_e(editor_id)}" data-tab="{_e(tab.lower())}" data-ne-equipped-item-id="{current_item_id}" data-ne-equipped-item-name="{_e(current)}" aria-controls="{_e(editor_id)}">
                  <span class="equipment-slot-art">{preview_html(slot, current, image_url)}</span>
                  <span class="equipment-slot-label">{_e(slot)}</span>
                  <span class="equipment-slot-item">{_e(_short(current or 'Leer', 33))}</span>
                  <span class="equipment-slot-state">{state_txt}</span>
                </button>"""
                if slot in upper_slots:
                    upper_cards.append(card)
                else:
                    lower_cards.append(card)
                editors.append(editor_html(tab, slot, slot_map.get(slot), idx))
        return f"""
        <section class="equipment-tab" data-equipment-tab="{_e(tab.lower())}"{('' if tab == 'Main' else ' hidden')}>
          <div class="equipment-window">
            <div class="equipment-window-head"><div><span class="eyebrow">Need-Bereich</span><h3>{_e(tab)}</h3></div><p>Slot anklicken und anschließend ausschließlich passende Items auswählen.</p></div>
            <div class="equipment-grid equipment-grid-upper">{''.join(upper_cards)}</div>
            <div class="equipment-section-gap" aria-hidden="true"></div>
            <div class="equipment-grid equipment-grid-lower">{''.join(lower_cards)}</div>
            <div class="equipment-editor-empty" data-editor-empty="{_e(tab.lower())}">⬆️ Klicke auf einen Equipment-Slot, um ihn zu bearbeiten.</div>
            <div class="equipment-editors">{''.join(editors)}</div>
          </div>
        </section>"""

    actor_hint = "Du bearbeitest deine eigene Needliste." if current_user else "Leitungsbearbeitung für dieses Mitglied."
    history_html = "" if compact else f"<h3>Änderungslog</h3>{_table(['Zeit','Status','Aktion','Bereich','Slot','Ergebnis'], req_rows, placeholder='Need-Änderungen durchsuchen…')}"

    return f"""
    <section class="panel equipment-need-panel" id="need-editor">
      <div class="equipment-need-heading">
        <div><h2>🎯 Needliste</h2><p class="muted">{_e(actor_hint)} Main wird zuerst angezeigt. Über den Umschalter wechselst du zu Secondary.</p></div>
        <div class="equipment-tabs" role="tablist" aria-label="Need-Bereich wechseln">
          <button type="button" class="equipment-tab-button active" data-switch-equipment="main" role="tab" aria-selected="true">⭐ Main</button>
          <button type="button" class="equipment-tab-button" data-switch-equipment="secondary" role="tab" aria-selected="false">🔁 Secondary</button>
        </div>
      </div>
      <style>
        .equipment-need-panel{{overflow:hidden}}
        .equipment-need-heading{{display:flex;align-items:center;justify-content:space-between;gap:18px;margin-bottom:16px}}
        .equipment-need-heading h2{{margin:0 0 5px}}
        .equipment-tabs{{display:flex;gap:8px;padding:5px;border-radius:15px;background:rgba(0,0,0,.28);border:1px solid rgba(214,168,79,.18)}}
        .equipment-tab-button{{border:0;border-radius:11px;padding:11px 17px;background:transparent;color:#c8c8c8;font-weight:900;cursor:pointer}}
        .equipment-tab-button.active{{background:linear-gradient(135deg,#b47a20,#e1b754);color:#171009;box-shadow:0 8px 20px rgba(0,0,0,.28)}}
        .need-planner-layout{{display:block}}
        .ne-side-panel{{min-width:0;border:1px solid rgba(214,168,79,.22);border-radius:20px;padding:13px;background:linear-gradient(160deg,rgba(20,17,14,.97),rgba(7,8,10,.96));box-shadow:0 18px 45px rgba(0,0,0,.28);display:flex;flex-direction:column}}
        .ne-side-head{{margin-bottom:10px}}.ne-side-head h3{{margin:2px 0 0;color:#f1d28a;font-size:20px}}
        .ne-attr-points,.ne-value-summary{{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:9px 10px;border-radius:12px;background:rgba(214,168,79,.07);border:1px solid rgba(214,168,79,.14);margin-bottom:10px;font-size:12px}}
        .ne-attr-points strong,.ne-value-summary strong{{font-size:19px;color:#f2d083}}
        .ne-attr-list{{display:grid;gap:7px}}
        .ne-attr-row{{display:grid;gap:6px;padding:9px;border-radius:12px;border:1px solid rgba(255,255,255,.075);background:rgba(255,255,255,.025)}}
        .ne-attr-row>span{{font-size:12px;font-weight:850;color:#d9e1e9}}
        .ne-attr-controls{{display:grid;grid-template-columns:32px 1fr 32px;gap:6px;align-items:center}}
        .ne-attr-controls button{{width:32px;height:30px;border-radius:9px;border:1px solid rgba(214,168,79,.24);background:rgba(214,168,79,.08);color:#f1d28a;font-size:18px;font-weight:900;cursor:pointer}}
        .ne-attr-controls button:hover{{background:rgba(214,168,79,.18)}}
        .ne-attr-controls strong{{text-align:center;font-size:18px}}
        .ne-attr-reset{{width:100%;margin-top:10px;justify-content:center}}
        .ne-attributes-panel p{{font-size:11px;margin:10px 0 0}}
        .ne-values-search{{width:100%;box-sizing:border-box;padding:9px 10px;border-radius:10px;border:1px solid rgba(255,255,255,.1);background:rgba(0,0,0,.3);color:inherit;margin-bottom:9px}}
        .ne-values-list{{display:grid;gap:7px;overflow:auto;max-height:760px;padding-right:2px}}
        .ne-value-group{{border:1px solid rgba(255,255,255,.065);border-radius:11px;overflow:hidden;background:rgba(255,255,255,.02)}}
        .ne-value-group h4{{margin:0;padding:7px 9px;background:rgba(214,168,79,.055);color:#e3c983;font-size:12px}}
        .ne-value-row{{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:7px;padding:6px 9px;border-top:1px solid rgba(255,255,255,.05);font-size:12px}}
        .ne-value-row span{{overflow-wrap:anywhere}}.ne-value-row b{{color:#e8edf2;text-align:right}}.ne-value-row small{{color:#81d58a;margin-left:5px}}
        .equipment-window{{min-width:0;width:100%;max-width:1180px;margin:0 auto;border:1px solid rgba(214,168,79,.24);border-radius:24px;padding:18px;background:linear-gradient(160deg,rgba(30,22,14,.98),rgba(8,8,9,.96));box-shadow:0 22px 55px rgba(0,0,0,.38)}}
        .equipment-window-head{{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-bottom:16px}}
        .equipment-window-head h3{{margin:2px 0 0;color:#f2d083;font-size:28px}}
        .equipment-window-head p{{margin:0;color:var(--muted);max-width:520px;text-align:right}}
        .equipment-grid{{display:grid;grid-template-columns:repeat(4,minmax(125px,1fr));gap:12px;align-items:stretch;padding:16px;border-radius:20px;background:radial-gradient(circle at center,rgba(128,91,28,.13),rgba(0,0,0,.26) 65%);border:1px solid rgba(255,255,255,.055)}}
        .equipment-grid-upper{{grid-template-areas:'. head head .' 'weapon1 chest hands cloak' 'weapon2 legs feet belt'}}
        .equipment-grid-lower{{grid-template-areas:'core1 . . .' 'core2 ring1 neck brooch' '. ring2 bracelet ear'}}
        .equipment-section-gap{{height:28px}}
        .equipment-slot{{position:relative;min-width:0;min-height:138px;padding:8px;border-radius:16px;border:1px solid rgba(255,255,255,.12);background:linear-gradient(180deg,rgba(25,25,27,.95),rgba(7,7,8,.96));color:inherit;cursor:pointer;overflow:hidden;display:grid;grid-template-rows:76px auto auto;gap:4px;text-align:center;transition:transform .14s ease,border-color .14s ease,box-shadow .14s ease}}
        .equipment-slot:hover,.equipment-slot.active{{transform:translateY(-2px);border-color:#d9a846;box-shadow:0 0 0 2px rgba(217,168,70,.14),0 12px 25px rgba(0,0,0,.32)}}
        .equipment-slot.filled{{border-color:rgba(107,165,255,.55)}}
        .equipment-slot.locked{{border-color:rgba(93,204,107,.6)}}
        .equipment-slot-art{{height:76px;display:grid;place-items:center;border-radius:11px;background:radial-gradient(circle at 50% 30%,rgba(104,124,198,.2),rgba(0,0,0,.45));overflow:hidden}}
        .equipment-img{{width:100%;height:100%;object-fit:contain;padding:5px}}
        .equipment-placeholder{{display:grid;place-items:center;width:100%;height:100%;font-size:38px;color:#dfb45c;filter:grayscale(.2)}}
        .equipment-slot-label{{font-size:13px;font-weight:950;color:#e6c06d;text-transform:uppercase;letter-spacing:.035em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}}
        .equipment-slot-item{{font-size:11px;color:#b9bec8;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}}
        .equipment-slot-state{{position:absolute;right:7px;top:7px;width:25px;height:25px;border-radius:8px;display:grid;place-items:center;background:rgba(0,0,0,.72);color:#f2c45f;font-weight:950;border:1px solid rgba(255,255,255,.12)}}
        .equipment-slot.locked .equipment-slot-state{{color:#91e69a}}
        .equipment-editor-empty{{margin-top:14px;padding:16px;text-align:center;border-radius:15px;border:1px dashed rgba(214,168,79,.24);color:var(--muted)}}
        .equipment-editors{{margin-top:14px}}
        .equipment-editor{{display:grid;grid-template-columns:150px minmax(0,1fr);gap:18px;padding:17px;border-radius:18px;background:rgba(0,0,0,.3);border:1px solid rgba(214,168,79,.2)}}
        .equipment-editor[hidden]{{display:none!important}}
        .equipment-editor-preview{{width:150px;height:150px;border-radius:18px;overflow:hidden;display:grid;place-items:center;background:radial-gradient(circle at 35% 25%,rgba(113,93,42,.25),rgba(0,0,0,.5));border:1px solid rgba(214,168,79,.2)}}
        .equipment-img.large{{padding:10px}}
        .equipment-placeholder.large{{font-size:58px}}
        .equipment-editor-main{{display:grid;gap:13px;min-width:0}}
        .equipment-editor-title{{display:flex;align-items:start;justify-content:space-between;gap:12px}}
        .equipment-editor-title div{{display:grid;gap:4px}}
        .equipment-editor-title span:first-child{{color:#e8bd65;font-weight:900;text-transform:uppercase;letter-spacing:.05em;font-size:13px}}
        .equipment-editor-title strong{{font-size:20px;overflow-wrap:anywhere}}
        .equipment-editor-picker select{{width:100%;min-width:0;padding:11px 12px;border-radius:11px;background:#08090c;color:var(--text);border:1px solid rgba(214,168,79,.2)}}
        .ne-picker-wrap{{display:grid;gap:10px}}
        .ne-weapon-label,.ne-item-label{{display:grid;gap:6px}}
        .ne-weapon-label>span,.ne-item-label>span{{font-size:12px;font-weight:900;text-transform:uppercase;letter-spacing:.05em;color:#d8bd7a}}
        .ne-picker-button{{width:100%;display:grid;grid-template-columns:58px minmax(0,1fr) auto;gap:12px;align-items:center;text-align:left;border:1px solid rgba(214,168,79,.24);background:linear-gradient(180deg,rgba(24,18,11,.95),rgba(8,8,10,.96));color:inherit;border-radius:15px;padding:10px;cursor:pointer;transition:border-color .14s ease,box-shadow .14s ease,transform .14s ease}}
        .ne-picker-button:hover,.ne-picker-button.open{{border-color:rgba(222,183,91,.82);box-shadow:0 0 0 2px rgba(214,168,79,.1),0 12px 30px rgba(0,0,0,.28);transform:translateY(-1px)}}
        .ne-picker-thumb{{width:56px;height:56px;border-radius:12px;display:grid;place-items:center;overflow:hidden;background:radial-gradient(circle at 35% 25%,rgba(94,74,158,.3),rgba(0,0,0,.42));border:1px solid rgba(150,115,220,.35);font-size:28px}}
        .ne-picker-thumb img{{width:100%;height:100%;object-fit:contain;padding:4px}}
        .ne-picker-copy{{display:grid;gap:3px;min-width:0}}
        .ne-picker-copy strong{{font-size:15px;color:#efd28d;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}}
        .ne-picker-copy small{{font-size:12px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}}
        .ne-picker-arrow{{font-size:22px;color:#e6bd65}}
        .ne-picker-pop{{position:fixed;z-index:12000;width:min(520px,calc(100vw - 24px));max-height:min(660px,82vh);border:1px solid rgba(214,168,79,.72);background:linear-gradient(150deg,#11151d,#080a0e);border-radius:18px;box-shadow:0 28px 100px rgba(0,0,0,.78);padding:11px}}
        .ne-picker-pop.mobile{{left:12px!important;right:12px!important;bottom:calc(12px + env(safe-area-inset-bottom));top:auto!important;width:auto!important;max-height:min(78vh,720px)}}
        .ne-picker-search{{width:100%;box-sizing:border-box;padding:12px 13px;border-radius:12px;border:1px solid rgba(214,168,79,.34);background:rgba(0,0,0,.46);color:inherit;margin-bottom:9px}}
        .ne-picker-list{{max-height:520px;overflow:auto;display:grid;grid-template-columns:1fr;gap:7px;padding-right:2px}}
        .ne-item-option{{display:grid;grid-template-columns:62px minmax(0,1fr) auto;gap:11px;align-items:center;border:1px solid rgba(255,255,255,.075);background:rgba(255,255,255,.035);border-radius:14px;padding:9px;cursor:pointer;text-align:left;color:inherit;touch-action:manipulation;-webkit-tap-highlight-color:transparent;min-height:78px}}
        .ne-item-option:hover{{border-color:rgba(214,168,79,.52);background:rgba(214,168,79,.09)}}
        .ne-item-option img{{width:60px;height:60px;object-fit:contain;border-radius:11px;background:rgba(0,0,0,.34);border:1px solid rgba(150,115,220,.28);padding:4px}}
        .ne-item-option-copy{{display:grid;gap:3px;min-width:0}}
        .ne-item-option strong{{color:#e8c986;font-size:14px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}}
        .ne-item-option small{{color:#aeb7c4;font-size:12px}}
        .ne-item-option em{{font-style:normal;color:#e6bd65;font-size:22px}}
        .ne-picker-empty{{padding:18px;text-align:center;color:#aeb7c4}}
        .ne-item-tooltip{{position:fixed;z-index:12100;width:min(390px,calc(100vw - 26px));pointer-events:none;border:1px solid rgba(214,168,79,.74);border-radius:16px;background:linear-gradient(145deg,#121722,#070a0f);box-shadow:0 24px 86px rgba(0,0,0,.82);padding:13px;color:#f3ead8}}
        .ne-tip-head{{display:grid;grid-template-columns:62px minmax(0,1fr);gap:11px;align-items:center;margin-bottom:8px}}
        .ne-tip-head img{{width:60px;height:60px;object-fit:contain;border-radius:11px;background:rgba(0,0,0,.36);border:1px solid rgba(150,115,220,.34);padding:4px}}
        .ne-tip-head strong{{display:block;color:#f0cf88;font-size:15px}}
        .ne-tip-head small{{color:#aeb7c4;font-size:12px}}
        .ne-tip-sec{{border-top:1px solid rgba(255,255,255,.085);padding-top:8px;margin-top:8px}}
        .ne-tip-sec h5{{margin:0 0 5px;color:#dce5ef;font-size:11px;text-transform:uppercase;letter-spacing:.055em}}
        .ne-tip-row{{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:9px;font-size:12px;padding:3px 0}}
        .ne-tip-row b{{color:#f0f3f7;text-align:right}}
        .ne-tip-trait{{font-size:12px;border:1px solid rgba(255,255,255,.065);border-radius:9px;padding:6px;margin-top:5px;background:rgba(255,255,255,.025)}}
        .ne-tip-trait b{{display:block;color:#dce5ef}}
        .ne-mobile-hint{{display:none;color:#aeb7c4;font-size:11px;margin-top:4px}}.ne-picker-close{{display:none;width:100%;margin-top:8px;padding:11px;border-radius:11px;border:1px solid rgba(214,168,79,.34);background:#1b1e25;color:#f0d392;font-weight:900;touch-action:manipulation}}
        .equipment-editor-actions{{display:flex;gap:9px;flex-wrap:wrap}}
        .equipment-unsaved{{padding:10px 12px;border-radius:11px;background:rgba(222,157,39,.12);border:1px solid rgba(222,157,39,.35);color:#f4cf78;font-weight:800;font-size:13px}}
        .equipment-editor.is-dirty{{border-color:rgba(222,157,39,.58);box-shadow:0 0 0 2px rgba(222,157,39,.1)}}
        .ghost{{background:#303442;color:var(--text)}}
        .need-state{{display:inline-flex;padding:6px 10px;border-radius:999px;font-size:11px;font-weight:900;text-transform:uppercase}}
        .need-state.filled{{color:#9dc5ff;background:rgba(80,135,230,.15);border:1px solid rgba(80,135,230,.25)}}
        .need-state.empty{{color:#bbb;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.1)}}
        .need-state.locked{{color:#94e49c;background:rgba(65,170,80,.14);border:1px solid rgba(65,170,80,.24)}}
        @media(max-width:1280px){{.need-planner-layout{{grid-template-columns:minmax(140px,165px) minmax(0,1fr) minmax(185px,220px);gap:9px}}.ne-side-panel{{padding:10px}}.equipment-window{{padding:13px}}.equipment-grid{{grid-template-columns:repeat(4,minmax(95px,1fr));gap:8px;padding:11px}}}}
        @media(max-width:1050px){{.need-planner-layout{{grid-template-columns:1fr 1fr;grid-template-areas:'attributes values' 'equipment equipment'}}.ne-attributes-panel{{grid-area:attributes}}.ne-values-panel{{grid-area:values}}.equipment-window{{grid-area:equipment}}.ne-values-list{{max-height:360px}}.equipment-grid{{grid-template-columns:repeat(4,minmax(100px,1fr))}}.equipment-grid-upper{{grid-template-areas:'. head head .' 'weapon1 chest hands cloak' 'weapon2 legs feet belt'}}.equipment-grid-lower{{grid-template-areas:'core1 . . .' 'core2 ring1 neck brooch' '. ring2 bracelet ear'}}.equipment-need-heading,.equipment-window-head{{align-items:flex-start;flex-direction:column}}.equipment-window-head p{{text-align:left}}}}
        @media(max-width:620px){{.need-planner-layout{{grid-template-columns:1fr;grid-template-areas:'attributes' 'equipment' 'values'}}.equipment-tabs{{width:100%}}.equipment-tab-button{{flex:1}}.equipment-window{{padding:11px;border-radius:18px}}.equipment-grid{{grid-template-columns:repeat(2,minmax(0,1fr));gap:7px;padding:9px}}.equipment-grid-upper{{grid-template-areas:'head head' 'weapon1 chest' 'weapon2 legs' 'hands cloak' 'feet belt'}}.equipment-grid-lower{{grid-template-areas:'core1 core1' 'core2 ring1' 'ring2 neck' 'bracelet brooch' 'ear ear'}}.equipment-section-gap{{height:18px}}.equipment-slot{{min-height:112px;grid-template-rows:58px auto auto;padding:6px}}.equipment-slot-art{{height:58px}}.equipment-placeholder{{font-size:28px}}.equipment-slot-label{{font-size:10px}}.equipment-slot-item{{font-size:9px}}.equipment-editor{{grid-template-columns:1fr}}.equipment-editor-preview{{width:110px;height:110px}}.equipment-editor-actions .btn{{flex:1 1 100%}}.ne-picker-button{{grid-template-columns:50px minmax(0,1fr) auto}}.ne-picker-thumb{{width:48px;height:48px}}.ne-item-tooltip{{display:none!important}}.ne-mobile-hint{{display:block}}body.ne-picker-open{{overflow:hidden}}.ne-values-list{{max-height:none}}.ne-picker-close{{display:block}}.ne-picker-pop.mobile{{z-index:30000!important}}}}
      </style>
      {board_html('Main', main_map)}
      {board_html('Secondary', sec_map)}
      {history_html}
      <script>
        (function equipmentNeedUI(){{
          const root = document.getElementById('need-editor');
          if (!root) return;
          const NE_ITEMS = window.BB_SHARED_ITEM_CATALOG || [];
          const NE_FILTERS = {slot_filters_json};
          let allowPageLeave = false;
          let nePop = null;
          let neTip = null;
          let neCurrentEditor = null;
          let neCurrentButton = null;

          function neEsc(value) {{
            return String(value ?? '').replace(/[&<>"']/g, function(c) {{
              return ({{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}})[c];
            }});
          }}
          function neNorm(value) {{
            return String(value || '').trim().toLocaleLowerCase('de-DE');
          }}
          function neMatchesSlot(item, slot) {{
            const filter = NE_FILTERS[slot] || {{canonical:'',category:'',subs:[],special:''}};
            if (filter.special === 'core') return !!item.is_core;
            const canonical = neNorm(item.slot || '');
            if (filter.canonical && canonical) return canonical === neNorm(filter.canonical);
            if (filter.category && neNorm(item.category) !== neNorm(filter.category)) return false;
            if (filter.subs && filter.subs.length && !filter.subs.some(function(sub) {{ return neNorm(sub) === neNorm(item.sub); }})) return false;
            return true;
          }}
          function neMatchesWeapon(item, weaponType) {{
            if (!weaponType) return true;
            const wanted = neNorm(weaponType);
            const itemWeapon = neNorm(item.weapon_type || item.sub || '');
            const haystack = neNorm((item.sub || '') + ' ' + (item.name || ''));
            return itemWeapon === wanted || haystack.includes(wanted);
          }}
          function neCanHover() {{ return window.matchMedia('(hover:hover) and (pointer:fine)').matches; }}
          function neIsMobile() {{ return window.innerWidth <= 620; }}
          function neClosePicker() {{
            if (nePop) {{ nePop.remove(); nePop = null; }}
            if (neCurrentButton) neCurrentButton.classList.remove('open');
            neCurrentButton = null;
            neCurrentEditor = null;
            document.body.classList.remove('ne-picker-open');
            neHideTip();
          }}
          function neHideTip() {{ if (neTip) neTip.style.display = 'none'; }}
          function neMoveTip(ev) {{
            if (!neTip || !ev || neIsMobile()) return;
            const pad = 16;
            const width = Math.min(390, window.innerWidth - 26);
            let x = ev.clientX + 18;
            let y = ev.clientY + 18;
            if (x + width > window.innerWidth - pad) x = ev.clientX - width - 18;
            if (y + 500 > window.innerHeight - pad) y = Math.max(pad, window.innerHeight - 510);
            neTip.style.left = x + 'px';
            neTip.style.top = y + 'px';
          }}
          function neItemRows(rows, maxRows) {{
            if (!Array.isArray(rows) || !rows.length) return '';
            return rows.slice(0, maxRows || 8).map(function(row) {{
              if (!row) return '';
              const label = String(row.label || row.name || '').replace(/:$/,'').trim();
              const value = row.value ?? row.text ?? '';
              return '<div class="ne-tip-row"><span>' + neEsc(label) + '</span><b>' + neEsc(value) + '</b></div>';
            }}).join('');
          }}
          function neItemTipHtml(item) {{
            const detail = item.detail || {{}};
            const primary = neItemRows(detail.primary || [], 7);
            const bonus = neItemRows(detail.bonus || [], 9);
            const stats = detail.stats || {{}};
            const statRows = Object.entries(stats).slice(0, 9).map(function(pair) {{
              return '<div class="ne-tip-row"><span>' + neEsc(pair[0]) + '</span><b>' + neEsc(pair[1]) + '</b></div>';
            }}).join('');
            const traits = Array.isArray(detail.traits) ? detail.traits.slice(0, 8).map(function(trait) {{
              const values = Array.isArray(trait.values) ? trait.values.join(' | ') : (trait.values || '');
              return '<div class="ne-tip-trait"><b>' + neEsc(trait.name || '') + '</b><span>' + neEsc(values) + '</span></div>';
            }}).join('') : '';
            const passive = detail.passive && (detail.passive.name || detail.passive.text)
              ? '<div class="ne-tip-sec"><h5>Passiv / Effekt</h5><div class="ne-tip-trait"><b>' + neEsc(detail.passive.name || 'Effekt') + '</b><span>' + neEsc(detail.passive.text || '') + '</span></div></div>'
              : '';
            const damage = (detail.damage_min || detail.damage_max)
              ? '<div class="ne-tip-row"><span>Schaden</span><b>' + neEsc(detail.damage_min || '—') + ' – ' + neEsc(detail.damage_max || '—') + '</b></div>'
              : '';
            const defense = detail.defense
              ? '<div class="ne-tip-row"><span>Verteidigung</span><b>' + neEsc(detail.defense) + '</b></div>'
              : '';
            const head = '<div class="ne-tip-head"><img src="' + neEsc(item.image || '') + '" onerror="this.style.visibility=&quot;hidden&quot;" alt=""><div><strong>' + neEsc(item.name) + '</strong><small>' + neEsc(item.rarity || '—') + ' · ' + neEsc(item.sub || item.category || '—') + (item.level ? ' · Lv. ' + neEsc(item.level) : '') + '</small></div></div>';
            return head
              + ((damage || defense || primary) ? '<div class="ne-tip-sec"><h5>Hauptwerte</h5>' + damage + defense + primary + '</div>' : '')
              + ((bonus || statRows) ? '<div class="ne-tip-sec"><h5>Zusatzwerte</h5>' + (bonus || statRows) + '</div>' : '')
              + (traits ? '<div class="ne-tip-sec"><h5>Eigenschaften</h5>' + traits + '</div>' : '')
              + passive;
          }}
          function neItemKey(value) {{
            return neNorm(value).replace(/\\([^)]*\\)\\s*$/,'').replace(/[^a-z0-9äöüß]+/g,'');
          }}
          function neFindItem(itemId, itemName) {{
            const numericId = Number(itemId || 0);
            if (numericId) {{
              const byId = NE_ITEMS.find(function(row) {{ return Number(row.id) === numericId; }});
              if (byId) return byId;
            }}
            const wanted = neItemKey(itemName || '');
            if (!wanted) return null;
            const exact = NE_ITEMS.find(function(row) {{ return neItemKey(row.name || '') === wanted; }});
            if (exact) return exact;
            const matches = NE_ITEMS.filter(function(row) {{
              const key = neItemKey(row.name || '');
              return key && wanted.length >= 8 && (key.includes(wanted) || wanted.includes(key));
            }});
            return matches.length === 1 ? matches[0] : null;
          }}
          function neShowTip(itemId, ev, itemName) {{
            if (!neCanHover() || neIsMobile()) return;
            const item = neFindItem(itemId, itemName);
            if (!item) return;
            if (!neTip) {{
              neTip = document.createElement('div');
              neTip.className = 'ne-item-tooltip';
              document.body.appendChild(neTip);
            }}
            neTip.innerHTML = neItemTipHtml(item);
            neTip.style.display = 'block';
            neMoveTip(ev);
          }}
          function neFilteredItems(editor, query) {{
            const slot = editor.dataset.slotName || '';
            const weaponField = editor.querySelector('.ne-weapon-type');
            const weaponType = weaponField ? weaponField.value : '';
            const needle = neNorm(query);
            return NE_ITEMS.filter(function(item) {{
              if (!neMatchesSlot(item, slot)) return false;
              if (slot.startsWith('Waffe') && !neMatchesWeapon(item, weaponType)) return false;
              if (needle && !neNorm(item.name).includes(needle)) return false;
              return true;
            }}).sort(function(a, b) {{
              const parseLevel = function(item) {{
                const raw = item && (item.level ?? item.item_level ?? item.required_level);
                const value = Number.parseFloat(String(raw ?? '').replace(',', '.'));
                return Number.isFinite(value) ? value : -1;
              }};
              const levelDiff = parseLevel(b) - parseLevel(a);
              if (levelDiff) return levelDiff;
              return String(a.name || '').localeCompare(String(b.name || ''), 'de');
            }});
          }}
          function neRenderOptions(query) {{
            if (!nePop || !neCurrentEditor) return;
            const list = nePop.querySelector('.ne-picker-list');
            const count = nePop.querySelector('[data-ne-result-count]');
            const items = neFilteredItems(neCurrentEditor, query || '');
            if (count) count.textContent = items.length + (items.length === 1 ? ' passendes Item' : ' passende Items') + ' – vollständig geladen';
            if (!items.length) {{
              list.innerHTML = '<div class="ne-picker-empty">Keine passenden Items für diesen Slot gefunden.</div>';
              return;
            }}
            list.innerHTML = items.map(function(item) {{
              const image = item.image
                ? '<img src="' + neEsc(item.image) + '" onerror="this.style.visibility=&quot;hidden&quot;" alt="">'
                : '<div class="ne-picker-thumb">🧩</div>';
              const meta = [item.rarity, item.sub || item.category, item.level ? 'Lv. ' + item.level : ''].filter(Boolean).join(' · ');
              return '<button type="button" class="ne-item-option" data-ne-item-id="' + Number(item.id) + '" data-ne-item-name="' + neEsc(item.name || '') + '">' + image + '<span class="ne-item-option-copy"><strong>' + neEsc(item.name) + '</strong><small>' + neEsc(meta || 'Item-Datenbank') + '</small></span><em>＋</em></button>';
            }}).join('');
            list.querySelectorAll('[data-ne-item-id]').forEach(function(option) {{
              const itemId = Number(option.dataset.neItemId || 0);
              option.addEventListener('click', function() {{ neChooseItem(itemId); }});
              option.addEventListener('mouseenter', function(ev) {{ neShowTip(itemId, ev, option.dataset.neItemName || ''); }});
              option.addEventListener('mousemove', neMoveTip);
              option.addEventListener('mouseleave', neHideTip);
            }});
          }}
          function neOpenPicker(button) {{
            const editor = button.closest('.equipment-editor');
            if (!editor) return;
            const weaponField = editor.querySelector('.ne-weapon-type');
            if (editor.dataset.slotName && editor.dataset.slotName.startsWith('Waffe') && weaponField && !weaponField.value) {{
              weaponField.focus();
              window.alert('Bitte zuerst die Waffenart auswählen.');
              return;
            }}
            neClosePicker();
            neCurrentEditor = editor;
            neCurrentButton = button;
            button.classList.add('open');
            const rect = button.getBoundingClientRect();
            nePop = document.createElement('div');
            nePop.className = 'ne-picker-pop';
            if (neIsMobile()) {{
              nePop.classList.add('mobile');
              document.body.classList.add('ne-picker-open');
            }} else {{
              nePop.style.left = Math.max(12, Math.min(rect.left, window.innerWidth - 540)) + 'px';
              nePop.style.top = Math.max(12, Math.min(rect.bottom + 8, window.innerHeight - 680)) + 'px';
            }}
            nePop.innerHTML = '<input class="ne-picker-search" type="search" placeholder="Optional filtern …"><div class="ne-picker-count" data-ne-result-count aria-live="polite"></div><div class="ne-picker-list"></div><div class="ne-mobile-hint">Item antippen, um es direkt auszuwählen.</div><button type="button" class="ne-picker-close">Schließen</button>';
            document.body.appendChild(nePop);
            const search = nePop.querySelector('.ne-picker-search');
            search.addEventListener('input', function() {{ neRenderOptions(search.value); }});
            const closeButton = nePop.querySelector('.ne-picker-close');
            if (closeButton) closeButton.addEventListener('click', neClosePicker);
            neRenderOptions('');
            if (!neIsMobile()) search.focus();
          }}
          function neChooseItem(itemId) {{
            const item = NE_ITEMS.find(function(row) {{ return Number(row.id) === Number(itemId); }});
            if (!item || !neCurrentEditor) return;
            const editor = neCurrentEditor;
            const field = editor.querySelector('[data-ne-item-value="1"]');
            const button = editor.querySelector('[data-ne-open-picker="1"]');
            if (!field || !button) return;
            field.value = item.name || '';
            field.dataset.itemId = String(item.id || '');
            field.dataset.image = item.image || '';
            field.dataset.label = item.name || '';
            const thumb = button.querySelector('[data-ne-picker-thumb="1"]');
            const label = button.querySelector('[data-ne-picker-label="1"]');
            const meta = button.querySelector('[data-ne-picker-meta="1"]');
            if (thumb) thumb.innerHTML = item.image ? '<img src="' + neEsc(item.image) + '" alt="">' : '<span>' + neEsc(editor.dataset.emptyIcon || '🧩') + '</span>';
            if (label) label.textContent = item.name || 'Item auswählen';
            if (meta) meta.textContent = [item.rarity, item.sub || item.category, item.level ? 'Lv. ' + item.level : ''].filter(Boolean).join(' · ') || 'Item-Datenbank';
            updatePreview(editor);
            refreshDirty(editor);
            neClosePicker();
          }}

          function dirtyEditors(){{
            return Array.from(root.querySelectorAll('.equipment-editor.is-dirty'));
          }}
          function hasUnsavedChanges(){{ return dirtyEditors().length > 0; }}
          function confirmDiscard(message){{
            if (!hasUnsavedChanges()) return true;
            return window.confirm(message || 'Du hast eine Item-Auswahl geändert, aber noch nicht gespeichert. Änderungen wirklich verwerfen?');
          }}
          function markDirty(editor, dirty){{
            if (!editor) return;
            editor.classList.toggle('is-dirty', !!dirty);
            const warning = editor.querySelector('[data-unsaved-warning="1"]');
            if (warning) warning.hidden = !dirty;
          }}
          function editorIsDirty(editor){{
            if (!editor || !editor.matches('form')) return false;
            return Array.from(editor.querySelectorAll('[data-dirty-field="1"]')).some(function(field){{
              return String(field.value || '') !== String(field.dataset.initialValue || '');
            }});
          }}
          function refreshDirty(editor){{ markDirty(editor, editorIsDirty(editor)); }}

          function activateTab(name, force){{
            const activeTab = root.querySelector('[data-equipment-tab]:not([hidden])');
            if (!force && activeTab && activeTab.dataset.equipmentTab !== name && !confirmDiscard('Du hast eine ungespeicherte Item-Auswahl. Trotzdem zu ' + (name === 'main' ? 'Main' : 'Secondary') + ' wechseln?')) return false;
            neClosePicker();
            if (activeTab && activeTab.dataset.equipmentTab !== name) dirtyEditors().forEach(function(editor){{ markDirty(editor, false); }});
            root.querySelectorAll('[data-equipment-tab]').forEach(function(tab){{ tab.hidden = tab.dataset.equipmentTab !== name; }});
            root.querySelectorAll('[data-switch-equipment]').forEach(function(btn){{
              const active = btn.dataset.switchEquipment === name;
              btn.classList.toggle('active', active);
              btn.setAttribute('aria-selected', active ? 'true' : 'false');
            }});
            return true;
          }}
          function closeEditors(tabName, force){{
            if (!force && !confirmDiscard('Du hast eine ungespeicherte Item-Auswahl. Anderen Slot öffnen und Änderung verwerfen?')) return false;
            neClosePicker();
            if (force || hasUnsavedChanges()) dirtyEditors().forEach(function(editor){{ markDirty(editor, false); }});
            root.querySelectorAll('.equipment-editor[data-tab="' + tabName + '"]').forEach(function(editor){{ editor.hidden = true; }});
            root.querySelectorAll('.equipment-slot[data-tab="' + tabName + '"]').forEach(function(card){{ card.classList.remove('active'); }});
            const empty = root.querySelector('[data-editor-empty="' + tabName + '"]');
            if (empty) empty.hidden = false;
            return true;
          }}
          root.querySelectorAll('[data-switch-equipment]').forEach(function(btn){{
            btn.addEventListener('click', function(){{ activateTab(btn.dataset.switchEquipment, false); }});
          }});
          root.querySelectorAll('[data-open-equipment]').forEach(function(card){{
            card.addEventListener('click', function(){{
              const tabName = card.dataset.tab;
              const editorId = card.dataset.openEquipment;
              const editor = document.getElementById(editorId);
              if (!editor) return;
              if (!closeEditors(tabName, false)) return;
              editor.hidden = false;
              card.classList.add('active');
              const empty = root.querySelector('[data-editor-empty="' + tabName + '"]');
              if (empty) empty.hidden = true;
              setTimeout(function(){{
                editor.scrollIntoView({{behavior:'smooth',block:'nearest'}});
                const first = editor.querySelector('.ne-weapon-type,[data-ne-open-picker="1"],button');
                if (first) first.focus({{preventScroll:true}});
              }},20);
            }});
          }});
          function updatePreview(editor){{
            const field = editor.querySelector('[data-ne-item-value="1"]');
            const label = editor.querySelector('[data-preview-label="1"]');
            const box = editor.querySelector('[data-preview-box="1"]');
            if (!field || !label || !box) return;
            const itemLabel = field.value || 'Noch kein Item gewählt';
            const image = field.dataset.image || '';
            label.textContent = itemLabel;
            if (image) box.innerHTML = '<img class="equipment-img large" src="' + neEsc(image) + '" alt="" loading="lazy">';
            else box.innerHTML = '<div class="equipment-placeholder large">' + neEsc(editor.dataset.emptyIcon || '🧩') + '</div>';
          }}
          root.querySelectorAll('[data-live-preview="1"]').forEach(function(editor){{
            editor.querySelectorAll('[data-dirty-field="1"]').forEach(function(field){{
              field.dataset.initialValue = String(field.value || '');
              field.addEventListener('change', function(){{
                if (field.classList.contains('ne-weapon-type')) {{
                  const itemField = editor.querySelector('[data-ne-item-value="1"]');
                  if (itemField && itemField.value) {{
                    const selectedItem = NE_ITEMS.find(function(item) {{ return Number(item.id) === Number(itemField.dataset.itemId || 0); }});
                    if (selectedItem && !neMatchesWeapon(selectedItem, field.value)) {{
                      itemField.value = '';
                      itemField.dataset.itemId = '';
                      itemField.dataset.image = '';
                      itemField.dataset.label = '';
                      const pickButton = editor.querySelector('[data-ne-open-picker="1"]');
                      if (pickButton) {{
                        const pickLabel = pickButton.querySelector('[data-ne-picker-label="1"]');
                        const pickMeta = pickButton.querySelector('[data-ne-picker-meta="1"]');
                        const pickThumb = pickButton.querySelector('[data-ne-picker-thumb="1"]');
                        if (pickLabel) pickLabel.textContent = 'Item auswählen';
                        if (pickMeta) pickMeta.textContent = 'Passende Katalogeinträge';
                        if (pickThumb) pickThumb.innerHTML = '<span>' + neEsc(editor.dataset.emptyIcon || '🧩') + '</span>';
                      }}
                    }}
                  }}
                }}
                refreshDirty(editor);
                updatePreview(editor);
                    neClosePicker();
              }});
            }});
            editor.querySelectorAll('[data-ne-open-picker="1"]').forEach(function(button){{
              button.addEventListener('click', function(){{ neOpenPicker(button); }});
              button.addEventListener('mouseenter', function(ev){{
                const field = editor.querySelector('[data-ne-item-value="1"]');
                const itemId = Number(field ? field.dataset.itemId || 0 : 0);
                if (itemId || (field && field.value)) neShowTip(itemId, ev, field ? field.value : '');
              }});
              button.addEventListener('mousemove', neMoveTip);
              button.addEventListener('mouseleave', neHideTip);
            }});
            editor.addEventListener('submit', function(){{
              allowPageLeave = true;
              markDirty(editor, false);
              neClosePicker();
            }});
          }});

          root.querySelectorAll('[data-ne-equipped-item-id]').forEach(function(card){{
            const itemId = Number(card.dataset.neEquippedItemId || 0);
            const itemName = card.dataset.neEquippedItemName || '';
            if (!itemId && !itemName) return;
            card.addEventListener('mouseenter', function(ev){{ neShowTip(itemId, ev, itemName); }});
            card.addEventListener('mousemove', neMoveTip);
            card.addEventListener('mouseleave', neHideTip);
          }});

          document.addEventListener('click', function(ev){{
            if (nePop && !nePop.contains(ev.target) && !(ev.target.closest && ev.target.closest('[data-ne-open-picker="1"]'))) neClosePicker();
          }});
          document.addEventListener('keydown', function(ev){{ if (ev.key === 'Escape') neClosePicker(); }});
          window.addEventListener('resize', neClosePicker);

          document.addEventListener('click', function(ev){{
            if (!hasUnsavedChanges() || allowPageLeave) return;
            const link = ev.target.closest('a[href]');
            if (!link || link.closest('#need-editor')) return;
            const href = link.getAttribute('href') || '';
            if (!href || href.startsWith('#') || href.startsWith('javascript:')) return;
            if (!confirmDiscard('Du hast eine Item-Auswahl geändert, aber nicht gespeichert. Diese Seite wirklich verlassen?')) {{
              ev.preventDefault();
              ev.stopImmediatePropagation();
            }} else {{
              allowPageLeave = true;
            }}
          }}, true);
          window.addEventListener('beforeunload', function(ev){{
            if (!hasUnsavedChanges() || allowPageLeave) return;
            ev.preventDefault();
            ev.returnValue = '';
          }});

          const requestedTab = (new URLSearchParams(window.location.search).get('need_area') || 'main').toLowerCase();
          activateTab(requestedTab === 'secondary' ? 'secondary' : 'main', true);
        }})();
      </script>
    </section>
    """

def _guild_membership_duration(value: Any) -> str:
    joined = _dt_obj(value)
    if not joined:
        return "—"
    if joined.tzinfo is None:
        joined = joined.replace(tzinfo=timezone.utc)
    now = datetime.now(timezone.utc)
    if joined > now:
        return "seit heute"
    days = max(0, (now - joined).days)
    years = int(days // 365)
    remaining = int(days - years * 365)
    months = int(remaining // 30)
    rest_days = int(remaining - months * 30)
    parts: list[str] = []
    if years:
        parts.append(f"{years} Jahr" if years == 1 else f"{years} Jahren")
    if months and len(parts) < 2:
        parts.append(f"{months} Monat" if months == 1 else f"{months} Monaten")
    if not parts or (years == 0 and months == 0):
        parts.append(f"{rest_days} Tag" if rest_days == 1 else f"{rest_days} Tagen")
    return "seit " + ", ".join(parts[:2])


def _render_member_portal(data: dict[str, Any], user_id: int, request: Request, msg: str = "") -> str:
    if not data.get("ok"):
        return _html_shell(
            "Profil · Beer and Buffs Dashboard",
            f"<section class='panel'><h1>👤 Mein Profil</h1><p class='muted'>{_e(data.get('error'))}</p></section>",
            nav_mode="member",
        )
    if not _portal_can_view(request, int(user_id)):
        raise HTTPException(status_code=403, detail="Du darfst nur dein eigenes Profil sehen. Leitung/Admins sehen alle Mitglieder.")

    snap: dict[str, Any] = data.get("snapshot") or {}
    guild_id = _safe_guild_id(data)
    states = _dashboard_module_states(int(guild_id or 0))
    needlists_enabled = bool(states.get("needlists", False))
    points_enabled = bool(states.get("points", False))
    attendance_enabled = bool(states.get("attendance", False))
    auctions_enabled = bool(states.get("auctions", False))
    aion2_enabled = bool(_dashboard_module_setting_value(int(guild_id or 0), 'onboarding', 'aion2_enabled', False))
    names = _profile_name_map(snap)
    uid = int(user_id)
    current_user = _current_user(request)
    own_profile = int(_current_user_id(request) or 0) == uid
    now = datetime.now(timezone.utc)
    brand = _guild_brand(data)

    profiles = ((snap.get("profiles") or {}).get("items") or [])
    profile: dict[str, Any] = {}
    for row in profiles:
        if isinstance(row, dict) and _user_id(row.get("user_id") or row.get("member_id") or row.get("discord_id")) == uid:
            profile = row
            break
    stored_profile = profile.get("profile") if isinstance(profile.get("profile"), dict) else {}

    def profile_value(*keys: str, default: Any = "") -> Any:
        for key in keys:
            value = profile.get(key)
            if value not in (None, "", [], {}):
                return value
            value = stored_profile.get(key)
            if value not in (None, "", [], {}):
                return value
        return default

    display = str(
        profile_value("display_name", "server_name", "discord_name", "discord_username", "ingame_name")
        or names.get(uid)
        or f"User {uid}"
    )
    avatar_url = str(profile_value("avatar_url", "display_avatar_url", "discord_avatar_url") or "").strip()
    class_name = str(profile_value("class_name", "main_class", "character_class", "klasse", "class", "build_class", "weapon_combo") or "—")
    main_role = str(profile_value("main_role", "role_name", "class_role", "role") or "—")
    gearscore = str(profile_value("gearscore", "gear_score", "gs") or "—")

    latest_profile_update = _latest_profile_update_request(int(guild_id or 0), uid) if guild_id else {}
    update_status = str(latest_profile_update.get("status") or "").lower()
    published_at = _dt_obj(data.get("published_at"))
    requested_at = _dt_obj(latest_profile_update.get("requested_at"))
    use_profile_overlay = update_status in {"pending", "processing"}
    if update_status == "done" and requested_at and (not published_at or requested_at > published_at):
        use_profile_overlay = True
    if use_profile_overlay:
        class_name = str(latest_profile_update.get("class_name") or class_name or "—")
        main_role = str(latest_profile_update.get("main_role") or main_role or "—")
        gearscore = str(latest_profile_update.get("gearscore") or gearscore or "—")

    joined_raw = profile_value("guild_joined_at", "joined_guild_at", "member_since", "joined_since", "joined_at", "created_at")
    joined_text = _guild_membership_duration(joined_raw)
    guild_rank = str(profile_value("guild_rank", "rank_name", "rank", "guild_role", "member_rank") or "").strip()
    if not guild_rank:
        role_names = [str(r.get("role_name") or "") for r in (profile.get("roles") or []) if isinstance(r, dict)]
        preferred = next((name for name in role_names if any(term in name.casefold() for term in ("anführer", "gildenmeister", "leader", "berater", "wächter", "guardian"))), "")
        guild_rank = preferred or "Mitglied"

    requests = _need_change_requests(int(guild_id), user_id=uid, limit=40) if (guild_id and needlists_enabled) else []
    need_editor_actor = current_user if _current_user_id(request) == uid else None
    shared_item_catalog = _need_builder_items() if needlists_enabled else []
    shared_item_catalog_json = json.dumps(shared_item_catalog, ensure_ascii=False).replace("</", "<\/")
    need_editor = _render_need_editor_panel(uid, need_editor_actor, requests, snap, compact=True, item_catalog=shared_item_catalog) if needlists_enabled else ""
    need_info = _needs_by_user(snap).get(uid, {}) if needlists_enabled else {}
    main_needs = need_info.get("main") if isinstance(need_info, dict) and isinstance(need_info.get("main"), list) else []
    secondary_needs = need_info.get("secondary") if isinstance(need_info, dict) and isinstance(need_info.get("secondary"), list) else []
    need_count = len(main_needs) + len(secondary_needs)
    balance = _balance_map(snap).get(uid) if points_enabled else None

    attendance_player: dict[str, Any] = {}
    if attendance_enabled:
        try:
            attendance_payload = _attendance_stats_payload(data)
            attendance_player = next((p for p in (attendance_payload.get("player_rows") or []) if _user_id(p.get("user_id")) == uid), {})
        except Exception:
            attendance_player = {}

    def event_dt(ev: dict[str, Any]) -> Optional[datetime]:
        return _event_dt_obj(ev.get("when_iso") or ev.get("start_at") or ev.get("created_at"))

    def event_image(ev: dict[str, Any]) -> str:
        return _dashboard_event_image_url(ev)

    active_events = [ev for ev in _portal_active_events(snap, uid) if isinstance(ev, dict)]
    active_events.sort(key=lambda ev: event_dt(ev) or datetime.max.replace(tzinfo=BERLIN_TZ))

    week_start = (now - timedelta(days=now.weekday())).replace(hour=0, minute=0, second=0, microsecond=0)
    week_end = week_start + timedelta(days=7)
    all_events = [ev for ev in _events_items(snap) if isinstance(ev, dict)]
    week_events = [ev for ev in all_events if (event_dt(ev) and week_start <= event_dt(ev) < week_end)]
    week_yes = 0
    week_open = 0
    week_missed = 0
    for ev in week_events:
        status = _portal_event_status_for_user(ev, uid)
        dt = event_dt(ev)
        if status.startswith("✅"):
            week_yes += 1
        elif dt and dt < now and not _is_running_event(ev):
            week_missed += 1
        else:
            week_open += 1
    week_total = len(week_events)
    week_percent = round((week_yes / week_total) * 100) if week_total else 0

    auctions = [a for a in (((snap.get("loot") or {}).get("auctions") or {}).get("items") or []) if isinstance(a, dict)] if auctions_enabled else []
    won_auctions = sum(1 for a in auctions if _user_id(a.get("winner_user_id")) == uid) if auctions_enabled else 0

    def user_in_auction(a: dict[str, Any]) -> bool:
        if _user_id(a.get("top_bid_user_id")) == uid or _user_id(a.get("winner_user_id")) == uid:
            return True
        for bid in a.get("bids") or []:
            if isinstance(bid, dict) and _user_id(bid.get("user_id") or bid.get("bidder_id") or bid.get("member_id")) == uid:
                return True
        return False

    user_active_auctions = [a for a in _portal_active_auctions(snap) if isinstance(a, dict) and user_in_auction(a)]
    user_active_auctions = user_active_auctions[:3]

    absence_text = "Keine Abwesenheit"
    absence_state = "available"
    for absence in ((snap.get("absences") or {}).get("items") or []):
        if not isinstance(absence, dict) or _user_id(absence.get("user_id") or absence.get("member_id")) != uid:
            continue
        status_text = str(absence.get("status") or "").casefold()
        if any(term in status_text for term in ("abgelehnt", "rejected", "storniert", "cancelled", "gelöscht", "deleted")):
            continue
        start = _dt_obj(absence.get("start_at") or absence.get("start_at_text") or absence.get("from"))
        end = _dt_obj(absence.get("end_at") or absence.get("end_at_text") or absence.get("until"))
        if end and end < now:
            continue
        if start and start > now:
            absence_text = f"Geplant ab {_dt(start)}"
            absence_state = "planned"
        else:
            absence_text = "Aktuell abwesend"
            absence_state = "away"
        break

    def event_row(ev: dict[str, Any]) -> str:
        eid = str(ev.get("event_id") or ev.get("id") or "")
        title = str(ev.get("title") or ev.get("name") or eid or "Gildenevent")
        status = _portal_event_status_for_user(ev, uid)
        image = event_image(ev)
        image_html = f'<img src="{_e(image)}" alt="{_e(title)}" loading="lazy" onerror="this.style.display=\'none\';this.parentElement.dataset.failed=\'1\'">' if image else '<span class="profile-event-fallback">⚔️</span>'
        status_cls = "yes" if status.startswith("✅") else "maybe" if "Vielleicht" in status else "no" if "Abgemeldet" in status else "open"
        summary = _event_response_summary(snap, ev)
        yes_count = int(summary.get("yes_count") or 0)
        return f'''
        <article class="profile-event-row">
          <div class="profile-event-image">{image_html}</div>
          <div class="profile-event-copy">
            <h3>{_e(title)}</h3>
            <p>📅 {_e(_event_dt(ev.get("when_iso") or ev.get("start_at")))}</p>
            <small>Dein Status: <strong>{_e(status)}</strong></small>
          </div>
          <div class="profile-event-side"><span class="profile-status {status_cls}">{_e("Zugesagt" if status.startswith("✅") else status.replace("🟡 ", "").replace("❌ ", ""))}</span><small>👥 {yes_count} Zusagen</small></div>
        </article>'''

    upcoming_html = "".join(event_row(ev) for ev in active_events[:2]) or '<div class="profile-empty">Keine kommenden Events.</div>'

    def auction_row(a: dict[str, Any]) -> str:
        aid = str(a.get("auction_id") or a.get("id") or "")
        item = _loot_text(a.get("item_name") or a.get("item") or aid or "Auktion")
        phase = _phase_label(a)
        bid = a.get("top_bid_amount")
        bid_text = _fmt_ec(bid) if bid is not None else "noch kein Gebot"
        return f'''
        <article class="profile-auction-row">
          <div class="profile-auction-icon">⚒️</div>
          <div><h3>{_e(item)}</h3><p>{_e(phase)} · {_e(bid_text)}</p></div>
          <a class="profile-mini-link" href="/auction/{_e(aid)}">Öffnen</a>
        </article>'''

    auctions_html = "".join(auction_row(a) for a in user_active_auctions) or '<div class="profile-empty">Du bist aktuell an keiner laufenden Auktion beteiligt.</div>'

    txs = _tx_for_user(snap, uid, limit=5) if points_enabled else []
    activity_rows: list[str] = []
    for tx in txs:
        amount = int(_num(tx.get("amount"), 0))
        sign_cls = "plus" if amount >= 0 else "minus"
        activity_rows.append(
            f'<div class="profile-activity-row"><span class="profile-activity-icon">🪙</span><strong class="{sign_cls}">{_e(_fmt_ec(amount))}</strong><span>{_e(_short(tx.get("reason") or tx.get("raw_type") or "EC-Buchung", 90))}</span><small>{_e(_dt(tx.get("created_at")))}</small></div>'
        )
    activities_html = "".join(activity_rows) or '<div class="profile-empty">Noch keine Aktivitäten vorhanden.</div>'

    avatar_html = (
        f'<img src="{_e(avatar_url)}" alt="Discord-Profilbild von {_e(display)}" loading="eager">'
        if avatar_url
        else f'<img src="{_e(_brand_image("logo", "beer_and_buffs_logo.png"))}" alt="Profilbild" loading="eager">'
    )

    role_choices = ["DPS", "Tank", "Support", "Flex"]
    role_options: list[str] = []
    if main_role not in ("", "—") and main_role not in role_choices:
        role_options.append(f'<option value="{_e(main_role)}" selected>{_e(main_role)}</option>')
    for role_name in role_choices:
        selected_attr = " selected" if role_name.casefold() == main_role.casefold() else ""
        role_options.append(f'<option value="{_e(role_name)}"{selected_attr}>{_e(role_name)}</option>')

    profile_update_notice = ""
    if update_status in {"pending", "processing"}:
        profile_update_notice = '<div class="profile-save-state pending">⏳ Profiländerung wurde an den Bot gesendet und wird verarbeitet.</div>'
    elif update_status == "error":
        profile_update_notice = f'<div class="profile-save-state error">❌ Profiländerung fehlgeschlagen: {_e(latest_profile_update.get("error_text") or "Unbekannter Fehler")}</div>'

    admin_links = ""
    if _is_portal_admin(request) and not own_profile:
        admin_links = f'<a class="btn ghost" href="/member/{uid}">Leitungsprüfung</a>'
    msg_html = f'<div class="ok">{_e(msg)}</div>' if msg else ""
    profile_eyebrow = "Mein Profil" if own_profile else "Mitgliedsprofil"
    profile_heading = "Mein Profil" if own_profile else display
    profile_subtitle = "Deine persönliche Gildenübersicht" if own_profile else f"Gildenprofil von {display}"

    stat_parts = [
        f'<div class="profile-stat"><small>Deine Rolle</small><strong>{_e(main_role)}</strong><span>{_e(class_name)}</span></div>',
        f'<div class="profile-stat"><small>Teilnahmen diese Woche</small><strong>{week_yes} / {week_total}</strong><span>Events</span></div>',
        f'<div class="profile-stat"><small>Abwesenheitsstatus</small><strong>{"🌙" if absence_state != "available" else "✓"}</strong><span>{_e(absence_text)}</span></div>',
    ]
    if points_enabled: stat_parts.append(f'<div class="profile-stat"><small>Coins (EC)</small><strong>🪙 {_e(_fmt_ec(balance) if balance is not None else "—")}</strong><span>Verfügbar</span></div>')
    if auctions_enabled: stat_parts.append(f'<div class="profile-stat"><small>Auktionen gewonnen</small><strong>⚒️ {won_auctions}</strong><span>Insgesamt</span></div>')
    if needlists_enabled: stat_parts.append(f'<div class="profile-stat"><small>Needlisteneinträge</small><strong>📋 {need_count}</strong><span>Offen</span></div>')
    profile_stats_html = ''.join(stat_parts)
    middle_sections = [f'<section class="profile-section"><h2 class="profile-section-title">Deine kommenden Events</h2><div class="profile-event-list">{upcoming_html}</div><div class="profile-panel-footer"><a href="/member/events">Zu meinen Events</a></div></section>']
    if auctions_enabled: middle_sections.append(f'<section class="profile-section"><h2 class="profile-section-title">Deine aktiven Auktionen</h2><div class="profile-auction-list">{auctions_html}</div><div class="profile-panel-footer"><a href="/member/auctions">Auktionen öffnen</a></div></section>')
    middle_sections_html=''.join(middle_sections)
    bottom_sections=[]
    if points_enabled: bottom_sections.append(f'<section class="profile-section"><h2 class="profile-section-title">Letzte EC-Aktivitäten</h2><div class="profile-activity-list">{activities_html}</div><div class="profile-panel-footer"><a href="/member/ec">Zur EC-Historie</a></div></section>')
    bottom_sections.append(f'<section class="profile-section"><h2 class="profile-section-title">Eventbeteiligung · Diese Woche</h2><div class="profile-week"><div class="profile-donut"><div class="profile-donut-text"><strong>{week_percent}%</strong><span>{week_yes} / {week_total}<br>Events</span></div></div><div class="profile-week-legend"><div><span>🟢 Zugesagt</span><strong>{week_yes}</strong></div><div><span>🟡 Offen</span><strong>{week_open}</strong></div><div><span>🔴 Verpasst</span><strong>{week_missed}</strong></div></div></div></section>')
    bottom_sections_html=''.join(bottom_sections)
    edit_button = '<a class="btn ghost profile-edit-top" href="#profile-edit">✎ Profil bearbeiten</a>' if (own_profile and aion2_enabled) else ''
    if _is_portal_admin(request) and not own_profile: edit_button += f'<a class="btn ghost" href="/member/{uid}">Leitungsprüfung</a>'
    needlist_section = f"""<script>window.BB_SHARED_ITEM_CATALOG = {shared_item_catalog_json};</script><details class="profile-details" id="needlist-editor"><summary>Needliste bearbeiten</summary><div class="profile-details-body">{need_editor}</div></details>""" if needlists_enabled else ''
    history_section = f"""<details class="profile-details" id="profile-history"><summary>EC- und Eventhistorie</summary><div class="profile-details-body"><section class="grid">{_card('Reviews', attendance_player.get('reviews', 0), 'gewertete Events')}{_card('War da', attendance_player.get('present', 0), 'anwesend')}{_card('Teilweise', attendance_player.get('partial', 0), 'teilweise')}{_card('Nicht da', attendance_player.get('absent', 0), 'abwesend')}{_card('Quote', attendance_player.get('rate') or '—', 'Anwesenheit')}</section></div></details>""" if (points_enabled or attendance_enabled) else ''
    portal_nav=['<a href="/member">Startseite</a>','<a href="/member/events">Events</a>']
    if auctions_enabled: portal_nav.append('<a href="/member/auctions">Auktionen</a>')
    if needlists_enabled: portal_nav.append('<a href="#needlist-editor">Needliste</a>')

    body = f"""
    <style>
      .member-profile-dashboard{{display:grid;gap:16px}}
      .profile-section{{border:1px solid rgba(214,168,79,.30);background:linear-gradient(135deg,rgba(16,15,13,.95),rgba(5,6,6,.93));box-shadow:inset 0 0 0 1px rgba(255,255,255,.02);overflow:hidden}}
      .profile-section-title{{margin:0;padding:13px 17px;border-bottom:1px solid rgba(214,168,79,.22);color:#e7c477;font:700 18px Georgia,serif;text-transform:uppercase;letter-spacing:.04em}}
      .profile-top-grid{{display:grid;grid-template-columns:minmax(320px,.95fr) minmax(480px,1.35fr);gap:16px}}
      .profile-identity{{display:grid;grid-template-columns:170px minmax(0,1fr);gap:22px;align-items:center;padding:24px}}
      .profile-avatar-wrap{{display:grid;justify-items:center;gap:9px}}
      .profile-avatar-large{{width:150px;height:150px;padding:5px;border-radius:50%;border:2px solid #c89435;background:radial-gradient(circle,rgba(158,37,28,.55),rgba(0,0,0,.94));box-shadow:0 0 0 5px rgba(214,168,79,.08)}}
      .profile-avatar-large img{{width:100%;height:100%;object-fit:cover;border-radius:50%}}
      .profile-level{{margin-top:-28px;position:relative;display:grid;place-items:center;width:48px;height:48px;border-radius:50%;background:#17130d;border:2px solid #c89435;color:#f1d28a;font:700 17px Georgia,serif}}
      .profile-identity h1{{margin:0 0 5px;font-size:35px}}
      .profile-guild-line{{color:#d7b66c;font-family:Georgia,serif;margin-bottom:16px}}
      .profile-role-pills{{display:flex;flex-wrap:wrap;gap:8px;margin:13px 0}}
      .profile-role-pill{{padding:7px 11px;border:1px solid rgba(214,168,79,.35);background:rgba(214,168,79,.08);font-weight:800;text-transform:uppercase;font-size:12px}}
      .profile-role-pill.primary{{background:rgba(132,29,21,.42);border-color:rgba(204,76,54,.65)}}
      .profile-identity-meta{{display:grid;gap:7px;color:#d9c9aa}}
      .profile-stat-grid{{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:1px;background:rgba(214,168,79,.16)}}
      .profile-stat{{min-height:112px;padding:15px;display:grid;align-content:center;justify-items:center;text-align:center;background:linear-gradient(135deg,rgba(16,15,13,.98),rgba(5,6,6,.97))}}
      .profile-stat small{{color:#d5ad58;font:700 13px Georgia,serif;text-transform:uppercase;letter-spacing:.05em}}
      .profile-stat strong{{font:700 28px Georgia,serif;margin:10px 0 4px}}
      .profile-stat span{{color:#7dd067;font-size:13px}}
      .profile-middle-grid{{display:grid;grid-template-columns:1.05fr 1fr;gap:16px}}
      .profile-event-list,.profile-auction-list,.profile-activity-list{{padding:12px}}
      .profile-event-row{{display:grid;grid-template-columns:94px minmax(0,1fr) auto;gap:13px;align-items:center;padding:8px;border-bottom:1px solid rgba(214,168,79,.16)}}
      .profile-event-row:last-child{{border-bottom:0}}
      .profile-event-image{{height:76px;overflow:hidden;border:1px solid rgba(214,168,79,.28);background:#0d0d0c;display:grid;place-items:center}}
      .profile-event-image[data-failed="1"]::after{{content:"⚔️";font-size:32px}}
      .profile-event-image img{{width:100%;height:100%;object-fit:cover}}.profile-event-fallback{{font-size:32px}}
      .profile-event-copy h3,.profile-auction-row h3{{margin:0 0 5px;font-size:18px}}.profile-event-copy p,.profile-auction-row p{{margin:0 0 5px;color:#d2bd94;font-size:13px}}
      .profile-event-side{{display:grid;justify-items:end;gap:8px}}.profile-event-side small{{color:#c9b996}}
      .profile-status{{padding:6px 11px;border:1px solid rgba(214,168,79,.38);font:700 12px Georgia,serif;text-transform:uppercase}}
      .profile-status.yes{{background:rgba(46,105,31,.40);border-color:rgba(93,169,61,.58)}}.profile-status.maybe{{background:rgba(97,62,130,.34)}}.profile-status.no{{background:rgba(116,35,28,.38)}}
      .profile-panel-footer{{display:flex;justify-content:center;padding:10px;border-top:1px solid rgba(214,168,79,.20);background:rgba(122,28,20,.20)}}
      .profile-panel-footer a{{color:#efd18d;text-transform:uppercase;font:700 14px Georgia,serif}}
      .profile-auction-row{{display:grid;grid-template-columns:48px minmax(0,1fr) auto;gap:12px;align-items:center;padding:14px 8px;border-bottom:1px solid rgba(214,168,79,.16)}}
      .profile-auction-row:last-child{{border-bottom:0}}.profile-auction-icon{{font-size:28px;text-align:center}}.profile-mini-link{{color:#efd18d;font-weight:800}}
      .profile-bottom-grid{{display:grid;grid-template-columns:1.25fr .8fr .8fr;gap:16px}}
      .profile-activity-row{{display:grid;grid-template-columns:28px 90px minmax(0,1fr) auto;gap:10px;align-items:center;padding:10px 6px;border-bottom:1px solid rgba(214,168,79,.14);font-size:13px}}
      .profile-activity-row:last-child{{border-bottom:0}}.profile-activity-row .plus{{color:#69d56f}}.profile-activity-row .minus{{color:#ff6d67}}.profile-activity-row small{{color:#a99575}}
      .profile-week{{display:grid;justify-items:center;gap:14px;padding:22px}}
      .profile-donut{{--p:{week_percent};width:150px;height:150px;border-radius:50%;display:grid;place-items:center;background:conic-gradient(#d6a84f calc(var(--p)*1%),rgba(214,168,79,.12) 0);position:relative}}
      .profile-donut::after{{content:"";position:absolute;inset:14px;border-radius:50%;background:#0a0b0a;border:1px solid rgba(214,168,79,.25)}}
      .profile-donut-text{{position:relative;z-index:1;text-align:center}}.profile-donut-text strong{{display:block;font:700 30px Georgia,serif;color:#e4bc66}}.profile-donut-text span{{font-size:13px}}
      .profile-week-legend{{display:grid;gap:8px;width:100%}}.profile-week-legend div{{display:flex;justify-content:space-between;gap:12px}}
      .profile-actions{{display:grid;gap:10px;padding:16px}}.profile-action{{display:flex;justify-content:center;padding:13px;border:1px solid rgba(214,168,79,.38);background:rgba(214,168,79,.05);color:#efd18d;text-transform:uppercase;font:700 14px Georgia,serif}}
      .profile-action.primary{{background:rgba(127,30,22,.38);border-color:rgba(188,63,45,.6)}}
      .profile-details{{margin-top:16px;border:1px solid rgba(214,168,79,.30);background:rgba(8,8,7,.92)}}
      .profile-details>summary{{list-style:none;cursor:pointer;padding:15px 18px;color:#efd18d;font:700 16px Georgia,serif;text-transform:uppercase}}.profile-details>summary::-webkit-details-marker{{display:none}}.profile-details[open]>summary{{border-bottom:1px solid rgba(214,168,79,.18)}}
      .profile-details-body{{padding:16px}}
      .profile-edit-grid{{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}}.profile-edit-grid label{{display:grid;gap:6px;color:#c9b894;font-size:12px;text-transform:uppercase;font-weight:800}}
      .profile-edit-grid input,.profile-edit-grid select{{width:100%;padding:11px 12px;border:1px solid rgba(214,168,79,.25);background:rgba(0,0,0,.35);color:var(--text)}}
      .profile-save-bar{{display:flex;justify-content:flex-end;padding-top:14px}}.profile-save-state{{margin-bottom:12px;padding:11px 13px;border-radius:8px}}.profile-save-state.pending{{background:rgba(214,168,79,.10);color:#f0d58f}}.profile-save-state.error{{background:rgba(211,82,82,.10);color:#ffaaaa}}
      .profile-empty{{padding:24px;color:var(--muted);text-align:center}}
      .profile-hero-actions{{display:flex;gap:8px;align-items:center;flex-wrap:wrap}}.profile-edit-top{{padding:9px 12px!important;font-size:12px!important}}
      .aion2-profile-panel{{margin-top:16px}}.aion2-profile-head{{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:10px}}.aion2-profile-head h2{{margin:0}}
      .aion2-profile-editor{{margin-top:14px;border-top:1px solid rgba(214,168,79,.18)}}.aion2-profile-editor>summary{{cursor:pointer;list-style:none;padding:12px 4px 4px;color:#e8c77e;font-weight:800}}.aion2-profile-editor>summary::-webkit-details-marker{{display:none}}
      .aion2-profile-form{{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin-top:12px}}.aion2-profile-form label{{display:grid;gap:5px;color:#c9b894;font-size:11px;font-weight:800;text-transform:uppercase}}.aion2-profile-form input,.aion2-profile-form select{{width:100%;min-width:0;box-sizing:border-box;padding:10px 11px;border:1px solid rgba(214,168,79,.25);background:rgba(0,0,0,.35);color:var(--text)}}.aion2-profile-form small{{color:var(--muted);text-transform:none;font-weight:400}}.aion2-save-row{{grid-column:1/-1;display:flex;justify-content:flex-end;padding-top:4px}}
      @media(max-width:1100px){{.profile-top-grid,.profile-middle-grid,.profile-bottom-grid{{grid-template-columns:1fr}}.profile-stat-grid{{grid-template-columns:repeat(3,1fr)}}}}
      @media(max-width:700px){{.profile-topnav{{display:none!important}}.profile-page-hero{{margin-top:74px!important;padding:15px!important;min-height:0!important;display:grid!important;gap:10px!important}}.profile-page-hero h1{{font-size:30px!important;line-height:1!important;margin:3px 0 0!important}}.profile-page-hero p{{font-size:11px!important;margin:5px 0 0!important}}.profile-hero-actions{{justify-content:flex-start}}.member-profile-dashboard{{gap:10px;min-width:0}}.profile-top-grid,.profile-middle-grid,.profile-bottom-grid{{grid-template-columns:1fr!important;gap:10px}}.profile-identity{{grid-template-columns:82px minmax(0,1fr);gap:12px;padding:13px;text-align:left}}.profile-avatar-large{{width:76px;height:76px;padding:3px}}.profile-level{{width:34px;height:34px;font-size:11px;margin-top:-20px}}.profile-identity h1{{font-size:22px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}}.profile-guild-line{{font-size:11px;margin-bottom:8px}}.profile-role-pills{{justify-content:flex-start;margin:7px 0;gap:5px}}.profile-role-pill{{padding:4px 7px;font-size:9px}}.profile-identity-meta{{font-size:10px;gap:3px}}.profile-stat-grid{{grid-template-columns:repeat(2,minmax(0,1fr))}}.profile-stat{{min-height:82px;padding:9px 7px}}.profile-stat small{{font-size:9px}}.profile-stat strong{{font-size:19px;margin:5px 0 2px}}.profile-stat span{{font-size:9px}}.profile-section-title{{padding:10px 12px;font-size:13px}}.profile-event-list,.profile-auction-list,.profile-activity-list{{padding:7px}}.profile-event-row{{grid-template-columns:62px minmax(0,1fr);gap:8px;padding:7px}}.profile-event-image{{height:54px}}.profile-event-copy h3{{font-size:14px}}.profile-event-copy p,.profile-event-copy small{{font-size:9px}}.profile-event-side{{grid-column:1/-1;display:flex;justify-content:space-between;font-size:9px}}.profile-auction-row{{grid-template-columns:36px minmax(0,1fr) auto;padding:9px 5px;gap:7px}}.profile-activity-row{{grid-template-columns:22px 70px minmax(0,1fr);gap:6px;font-size:10px}}.profile-activity-row small{{grid-column:2/-1}}.profile-week{{padding:14px}}.profile-donut{{width:112px;height:112px}}.profile-donut-text strong{{font-size:23px}}.profile-donut-text span{{font-size:10px}}.aion2-profile-panel{{margin-top:10px;padding:12px!important}}.aion2-profile-grid{{grid-template-columns:repeat(2,minmax(0,1fr))!important;gap:7px!important}}.aion2-profile-grid .card{{min-width:0!important;padding:9px!important}}.aion2-profile-form{{grid-template-columns:1fr;gap:8px}}.aion2-save-row{{grid-column:auto}}.aion2-save-row .btn{{width:100%}}.profile-details{{margin-top:10px}}.profile-details>summary{{padding:11px 12px;font-size:12px}}.profile-details-body{{padding:10px}}}}
    </style>
    <nav class="topnav profile-topnav">{"".join(portal_nav)}</nav>
    <section class="hero profile-page-hero"><div><div class="eyebrow">{_e(profile_eyebrow)}</div><h1>{_e(profile_heading)}</h1><p class="muted">{_e(profile_subtitle)}</p></div><div class="profile-hero-actions">{edit_button}</div></section>
    {msg_html}
    {profile_update_notice}
    <main class="member-profile-dashboard">
      <div class="profile-top-grid">
        <section class="profile-section profile-identity">
          <div class="profile-avatar-wrap"><div class="profile-avatar-large">{avatar_html}</div><div class="profile-level">{_e(gearscore if gearscore != '—' else 'GS')}</div></div>
          <div>
            <h1>{_e(display)}</h1>
            <div class="profile-guild-line">🛡️ {_e(brand.get('display_name') or 'Beer and Buffs')} · {_e(guild_rank)}</div>
            <div class="profile-role-pills"><span class="profile-role-pill primary">{_e(main_role)}</span><span class="profile-role-pill">{_e(class_name)}</span></div>
            <div class="profile-identity-meta"><span>⚙️ Gearscore: <strong>{_e(gearscore)}</strong></span><span>📅 Aktiv { _e(joined_text) }</span></div>
          </div>
        </section>
        <section class="profile-section profile-stat-grid">{profile_stats_html}</section>
      </div>

      {_aion2_profile_panel(data, uid, current_user) if aion2_enabled else ''}

      <div class="profile-middle-grid">{middle_sections_html}</div>
      <div class="profile-bottom-grid">{bottom_sections_html}</div>
    </main>
    {needlist_section}
    {history_section}

    <script>
      (function openProfileHash(){{
        function openTarget(){{
          const id = (window.location.hash || '').slice(1);
          if (!id) return;
          const target = document.getElementById(id);
          if (target && target.tagName === 'DETAILS') target.open = true;
        }}
        document.addEventListener('click', function(ev){{
          const link = ev.target.closest('a[href^="#"]');
          if (!link) return;
          const target = document.querySelector(link.getAttribute('href'));
          if (target && target.tagName === 'DETAILS') target.open = true;
        }});
        window.addEventListener('hashchange', openTarget);
        openTarget();
      }})();
    </script>
    """
    return _html_shell(f"{display} · {'Mein Profil' if own_profile else 'Mitgliedsprofil'}", body, nav_mode=_nav_mode_for_request(request), active_nav_href=("/portal" if own_profile else "/member/members"))

def _member_home_event_rows(events: list[dict[str, Any]], user_id: int) -> str:
    if not events:
        return '<div class="empty">Keine laufenden Events.</div>'
    items = []
    for ev in events[:2]:
        eid = str(ev.get("event_id") or ev.get("id") or "")
        title = ev.get("title") or ev.get("name") or eid or "Event"
        meta = f"{_event_dt(ev.get('when_iso') or ev.get('start_at') or ev.get('created_at'))} · {_event_status_text(ev)} · Deine Anmeldung: {_portal_event_status_for_user(ev, user_id)}"
        items.append(f'<div class="member-summary-item"><div><div class="member-summary-title">{_cell(_event_link(eid, title))}</div><div class="member-summary-meta">{_e(meta)}</div></div></div>')
    return '<div class="member-summary-list">' + ''.join(items) + '</div>'

def _member_home_auction_rows(auctions: list[dict[str, Any]], snap: dict[str, Any]) -> str:
    if not auctions:
        return '<div class="empty">Keine laufenden Auktionen.</div>'
    items = []
    for a in auctions[:4]:
        aid = str(a.get("auction_id") or "")
        title = _loot_text(a.get("item_name") or a.get("item") or aid)
        count_title, count_value, _ = _auction_count_label(a)
        meta = f"{_phase_label(a)} · {count_value} {count_title} · {_auction_leader_or_roll_text(a, snap)} · {_auction_timer_text(a)}"
        items.append(f'<div class="member-summary-item"><div><div class="member-summary-title">{_cell(_auction_link(aid, title))}</div><div class="member-summary-meta">{_e(meta)}</div></div></div>')
    return '<div class="member-summary-list">' + ''.join(items) + '</div>'

def _aion2_home_map_panel(guild_id: int) -> str:
    """Aion-2-Livekarte auf der Startseite.

    Fextralife blockiert die Einbettung im Browser. Das Dashboard nutzt daher
    denselben iframe-tauglichen Kartenanbieter, der bereits für T&L vorhanden ist.
    """
    if not bool(_dashboard_module_setting_value(guild_id, "onboarding", "aion2_enabled", False)):
        return ""
    direct_url = AION2_MAP_DIRECT_URL
    embed_url = AION2_MAP_EMBED_URL
    return f"""
    <section class="panel aion-home-map" id="aion2-map">
      <div class="aion-map-head">
        <div>
          <div class="eyebrow">Aion 2</div>
          <h2>🗺️ Interaktive Karte</h2>
          <p class="muted">Live-Karte von IMapp. Gebiete und Marker können direkt in der Karte gewechselt werden.</p>
        </div>
        <a class="btn secondary" href="{_e(direct_url)}" target="_blank" rel="noopener noreferrer">Karte groß öffnen ↗</a>
      </div>
      <div class="aion-map-frame-wrap">
        <div id="aion-map-loader" class="aion-map-fallback">🗺️ Aion-2-Karte wird geladen …</div>
        <iframe id="aion-map-frame" src="{_e(embed_url)}" title="Aion 2 Interactive Map" loading="lazy" referrerpolicy="no-referrer-when-downgrade" allow="fullscreen"></iframe>
      </div>
    </section>
    <style>
      .aion-home-map{{margin:18px 0}}
      .aion-map-head{{display:flex;justify-content:space-between;gap:16px;align-items:center;flex-wrap:wrap;margin-bottom:12px}}
      .aion-map-head h2{{margin:2px 0 5px}}
      .aion-map-frame-wrap{{position:relative;border:1px solid rgba(214,168,79,.28);background:#07090d;min-height:640px;overflow:hidden;border-radius:10px}}
      #aion-map-frame{{position:relative;z-index:1;display:block;width:100%;height:70vh;min-height:640px;border:0;background:#07090d}}
      .aion-map-fallback{{position:absolute;z-index:0;inset:0;display:grid;place-items:center;padding:32px;text-align:center;color:#9da8b6;background:linear-gradient(135deg,#090b10,#111722)}}
      @media(max-width:760px){{#aion-map-frame{{height:68vh;min-height:520px}}.aion-map-frame-wrap{{min-height:520px}}}}
    </style>
    <script>
      (function aionMapLoader(){{
        const frame=document.getElementById('aion-map-frame');
        const loader=document.getElementById('aion-map-loader');
        if(!frame||!loader)return;
        frame.addEventListener('load',()=>{{loader.style.display='none';}});
      }})();
    </script>
    """

def _render_member_home(data: dict[str, Any], request: Request) -> str:
    if not data.get("ok"):
        return _html_shell(
            "Mitgliederbereich · Guild Platform",
            f"<section class='panel'><h1>🏠 Mitgliederbereich</h1><p class='muted'>{_e(data.get('error'))}</p></section>",
            nav_mode="member",
        )

    user = _current_user(request) or {}
    uid = _current_user_id(request)
    snap: dict[str, Any] = data.get("snapshot") or {}
    guild_id = int(_safe_guild_id(data) or 0)
    states = _dashboard_module_states(guild_id)
    names = _profile_name_map(snap)
    display = names.get(int(uid), str(user.get("username") or "Mitglied")) if uid else str(user.get("username") or "Mitglied")
    guild = snap.get("guild") or {}
    member_filter = guild.get("member_filter") if isinstance(guild.get("member_filter"), dict) else {}
    member_count = int(_num(member_filter.get("eligible_count"), 0))

    now = datetime.now(BERLIN_TZ)
    all_events = [ev for ev in _events_items(snap) if isinstance(ev, dict)]
    active_events = []
    for ev in all_events:
        dt = _event_dt_obj(ev.get("when_iso") or ev.get("start_at") or ev.get("created_at"))
        if _is_running_event(ev) or (dt is not None and dt >= now):
            active_events.append(ev)
    active_events.sort(key=lambda ev: _event_dt_obj(ev.get("when_iso") or ev.get("start_at") or ev.get("created_at")) or datetime.max.replace(tzinfo=BERLIN_TZ))

    auctions: list[dict[str, Any]] = []
    if states.get("auctions", False):
        raw_auctions = (((snap.get("loot") or {}).get("auctions") or {}).get("items") or [])
        auctions = [a for a in raw_auctions if isinstance(a, dict) and _loot_is_active(a)]
        auctions.sort(key=lambda a: _auction_timer_dt(a) or datetime.max.replace(tzinfo=BERLIN_TZ))

    cards = [
        _card("Mitglieder", member_count, "aktuell in der Gilde"),
        _card("Events", len(active_events), "laufend oder geplant"),
        _card("Aktive Module", sum(1 for key in OPTIONAL_MODULE_KEYS if states.get(key, False)), "optionale Systeme"),
        _card("Boss", "27 Min.", "Abyss · Nordfestung"),
    ]
    if states.get("points", False):
        my_balance = _balance_map(snap).get(int(uid or 0)) if uid else None
        cards.append(_card("Meine Punkte", _fmt_ec(my_balance) if my_balance is not None else "—", "Punktesystem aktiv"))
    if states.get("auctions", False):
        cards.append(_card("Auktionen", len(auctions), "aktuell aktiv"))

    nav = [
        '<a href="/member">Start</a>',
        '<a href="/member/events">Events</a>',
        '<a href="/member/members">Mitglieder</a>',
        '<a href="/announcements">Ankündigungen</a>',
        '<a href="/guides">Guides</a>',
    ]
    if states.get("member_portal", False):
        nav.append('<a href="/portal">Mein Portal</a>')
    if states.get("attendance", False):
        nav.append('<a href="/attendance">Attendance</a>')
    if states.get("points", False):
        nav.append('<a href="/member/ec">Meine Punkte</a>')
    if states.get("auctions", False):
        nav.append('<a href="/member/auctions">Auktionen</a>')

    sections = [f'''
      <section class="panel" id="events">
        <h2>📅 Nächste Events</h2>
        {_member_home_event_rows(active_events, int(uid or 0))}
        <p style="margin-top:14px"><a class="btn secondary" href="/member/events">Alle Events</a></p>
      </section>
    ''']
    if states.get("auctions", False):
        sections.append(f'''
          <section class="panel" id="auctions">
            <h2>🔨 Laufende Auktionen</h2>
            {_member_home_auction_rows(auctions, snap)}
            <p style="margin-top:14px"><a class="btn secondary" href="/member/auctions">Alle Auktionen</a></p>
          </section>
        ''')
    else:
        sections.append('''
          <section class="panel">
            <h2>👥 Gilde</h2>
            <p class="muted">Die Grundfunktionen bleiben bewusst schlank. Weitere Systeme können von der Gildenleitung unter Einstellungen → Module zugeschaltet werden.</p>
            <p><a class="btn secondary" href="/member/members">Mitgliederliste öffnen</a></p>
          </section>
        ''')

    brand = _guild_brand(snap)
    is_admin = _is_portal_admin(request)
    admin_tools = (_admin_tabs_style()+_admin_quick_links('')) if is_admin else ''
    aion_map_panel = _aion2_home_map_panel(guild_id)

    # Mobile Startseite bewusst extrem kompakt: drei Statuskacheln, bei Leitung
