def _dashboard_event_action_requests(guild_id: int, limit: int = 80, event_id: str = "") -> list[dict[str, Any]]:
    if not _database_url() or not guild_id:
        return []
    try:
        _ensure_admin_tables()
        conn = _pg_connect()
        try:
            with conn.cursor() as cur:
                if event_id:
                    cur.execute(
                        """
                        SELECT id, request_id, guild_id, event_id, action_type, status, payload_json, actor_id, actor_name, requested_at, claimed_at, processed_at, result_json
                        FROM dashboard_event_action_requests
                        WHERE guild_id = %s AND event_id = %s
                        ORDER BY requested_at DESC
                        LIMIT %s
                        """,
                        (int(guild_id), str(event_id), int(limit)),
                    )
                else:
                    cur.execute(
                        """
                        SELECT id, request_id, guild_id, event_id, action_type, status, payload_json, actor_id, actor_name, requested_at, claimed_at, processed_at, result_json
                        FROM dashboard_event_action_requests
                        WHERE guild_id = %s
                        ORDER BY requested_at DESC
                        LIMIT %s
                        """,
                        (int(guild_id), int(limit)),
                    )
                return [dict(r) for r in (cur.fetchall() or [])]
        finally:
            conn.close()
    except Exception:
        return []


def _event_action_counts(rows: list[dict[str, Any]]) -> dict[str, int]:
    c: dict[str, int] = {}
    for r in rows or []:
        s = str((r or {}).get("status") or "unknown").lower()
        c[s] = c.get(s, 0) + 1
    return c


def _enqueue_event_action_request(guild_id: int, action_type: str, payload: dict[str, Any], actor: dict[str, Any]) -> dict[str, Any]:
    if not _database_url():
        return {"ok": False, "error": "DATABASE_URL fehlt. Ohne Postgres kann das Dashboard keine Event-Aktion an den Bot übergeben."}
    if not guild_id:
        return {"ok": False, "error": "Guild-ID fehlt."}
    action = str(action_type or "").strip().lower()
    if action not in {"create", "edit", "delete", "rsvp", "lineup"}:
        return {"ok": False, "error": "Unbekannte Event-Aktion."}
    actor_id = str(actor.get("user_id") or "").strip()
    actor_name = str(actor.get("username") or actor_id or "Dashboard")
    event_id = str(payload.get("event_id") or "").strip()
    if action in {"edit", "delete", "rsvp", "lineup"} and not event_id:
        return {"ok": False, "error": "Event-ID fehlt."}
    if action == "rsvp":
        choice = normalize_event_role(payload.get("choice") or payload.get("response") or "")
        payload["choice"] = choice
        if choice not in {"TANK", "SUPPORT", "DPS", "BANK", "MAYBE", "NO"}:
            return {"ok": False, "error": "Ungültige RSVP-Auswahl."}
        if not actor_id.isdigit():
            return {"ok": False, "error": "Discord-Login erforderlich."}
    if action == "create" and not str(payload.get("title") or "").strip():
        return {"ok": False, "error": "Titel fehlt."}
    if action == "create" and not str(payload.get("channel_id") or "").strip():
        return {"ok": False, "error": "Zielkanal-ID fehlt."}
    request_id = f"dash-event-{int(time.time())}-{secrets.token_hex(6)}"
    payload = dict(payload)
    payload.update({
        "action_type": action,
        "requested_by": {"id": actor_id, "name": actor_name},
        "requested_at": datetime.now(timezone.utc).isoformat(),
        "source": "dashboard_event_action",
    })
    _ensure_admin_tables()
    conn = _pg_connect()
    try:
        with conn.cursor() as cur:
            if action == "rsvp":
                cur.execute(
                    """
                    UPDATE dashboard_event_action_requests
                    SET status = 'superseded', processed_at = NOW(), result_json = %s
                    WHERE guild_id = %s AND event_id = %s AND action_type = 'rsvp'
                      AND actor_id = %s AND status = 'pending'
                    """,
                    (json.dumps({"ok": False, "message": "Durch neuere Dashboard-RSVP ersetzt."}, ensure_ascii=False), int(guild_id), event_id, actor_id),
                )
            if action == "lineup":
                cur.execute(
                    """
                    UPDATE dashboard_event_action_requests
                    SET status = 'superseded', processed_at = NOW(), result_json = %s
                    WHERE guild_id = %s AND event_id = %s AND action_type = 'lineup'
                      AND status = 'pending'
                    """,
                    (json.dumps({"ok": False, "message": "Durch neuere Aufstellung ersetzt."}, ensure_ascii=False), int(guild_id), event_id),
                )
            cur.execute(
                """
                INSERT INTO dashboard_event_action_requests
                    (request_id, guild_id, event_id, action_type, status, payload_json, actor_id, actor_name, requested_at)
                VALUES (%s, %s, %s, %s, 'pending', %s, %s, %s, NOW())
                RETURNING id, request_id, status
                """,
                (request_id, int(guild_id), event_id, action, json.dumps(payload, ensure_ascii=False, separators=(",", ":")), actor_id, actor_name),
            )
            row = dict(cur.fetchone() or {})
            cur.execute(
                """
                INSERT INTO dashboard_admin_action_log
                    (guild_id, action_type, target_type, target_id, actor_id, actor_name, payload_json)
                VALUES (%s, %s, %s, %s, %s, %s, %s)
                """,
                (int(guild_id), f"event_action_{action}_create", "event", event_id or "new", actor_id, actor_name, json.dumps(payload, ensure_ascii=False)),
            )
        conn.commit()
        return {"ok": True, "request": row, "request_id": request_id}
    finally:
        conn.close()



def _event_lineup_candidates(event: dict[str, Any]) -> list[dict[str, Any]]:
    """Aktuelle Zusagen eines Events als eindeutige Drag-&-Drop-Kandidaten."""
    out: list[dict[str, Any]] = []
    seen: set[int] = set()
    role_order = {"TANK": 0, "SUPPORT": 1, "HEAL": 1, "HEALER": 1, "DPS": 2, "BANK": 3, "RESERVE": 3}
    groups = sorted(
        _event_yes_groups(event),
        key=lambda g: (role_order.get(str(g.get("role") or "").upper(), 20), str(g.get("role") or "").casefold()),
    )
    for group in groups:
        role_raw = str(group.get("role") or "Zusage").strip()
        role_key = role_raw.upper()
        role = {"SUPPORT": "Support", "HEALER": "Support", "HEAL": "Support", "TANK": "Tank", "DPS": "DPS", "BANK": "Reserve", "RESERVE": "Reserve"}.get(role_key, role_raw or "Zusage")
        for person in group.get("participants") or []:
            if not isinstance(person, dict):
                continue
            uid = _user_id(person.get("user_id") or person.get("id"))
            if not uid or uid in seen:
                continue
            seen.add(uid)
            out.append({
                "user_id": int(uid),
                "display_name": _event_person_name(person),
                "role": role,
            })
    return out


def _event_lineup_candidates_for_snapshot(snap: dict[str, Any], event: dict[str, Any]) -> list[dict[str, Any]]:
    """Zusagen stabil aus Eventobjekt + RSVP-Mirror zusammenführen.

    Der Event-Snapshot kann während eines Bot-Publishes kurz ohne eingebettete
    Teilnehmer vorliegen. Für die Drag-&-Drop-Aufstellung darf dadurch eine
    bereits sichtbare Zuordnung nicht wieder verschwinden.
    """
    out = list(_event_lineup_candidates(event))
    seen = {int(x.get("user_id") or 0) for x in out if isinstance(x, dict)}
    event_id = str(event.get("event_id") or event.get("id") or "").strip()
    rows = ((snap.get("event_rsvps") or {}).get("items") or []) if isinstance(snap.get("event_rsvps"), dict) else []
    for row in rows:
        if not isinstance(row, dict) or str(row.get("event_id") or "").strip() != event_id:
            continue
        uid = _user_id(row.get("user_id") or row.get("id"))
        if not uid or uid in seen:
            continue
        response = str(row.get("response") or row.get("status") or "").strip().lower()
        role_raw = str(row.get("role_name") or row.get("role") or "Zusage").strip()
        role_l = role_raw.lower()
        if response in {"no", "nein", "absent", "abgemeldet", "declined", "deny", "maybe", "vielleicht", "tentative", "unsure"}:
            continue
        if role_l in {"no", "nein", "abgemeldet", "maybe", "vielleicht"}:
            continue
        role_key = role_raw.upper()
        role = {"SUPPORT": "Support", "HEALER": "Support", "HEAL": "Support", "TANK": "Tank", "DPS": "DPS", "BANK": "Reserve", "RESERVE": "Reserve"}.get(role_key, role_raw or "Zusage")
        out.append({
            "user_id": int(uid),
            "display_name": str(row.get("display_name") or row.get("name") or row.get("server_name") or f"User {uid}"),
            "role": role,
        })
        seen.add(uid)
    return out


def _event_lineup_default(event: dict[str, Any], *, group_size: int = 6, candidates: Optional[list[dict[str, Any]]] = None) -> dict[str, Any]:
    candidates = list(candidates) if candidates is not None else _event_lineup_candidates(event)
    size = max(1, min(24, int(group_size or 6)))
    group_count = max(1, (len(candidates) + size - 1) // size) if candidates else 1
    return {
        "group_size": size,
        "group_count": group_count,
        "groups": [{"name": f"Gruppe {i}", "members": []} for i in range(1, group_count + 1)],
        "bench": [],
        "published": False,
    }


def _load_event_lineup(guild_id: int, event_id: str, event: Optional[dict[str, Any]] = None, *, candidates: Optional[list[dict[str, Any]]] = None) -> dict[str, Any]:
    if not guild_id or not event_id or not _database_url():
        return _event_lineup_default(event or {}, candidates=candidates)
    _ensure_admin_tables()
    conn = _pg_connect()
    try:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT lineup_json, published, discord_channel_id, discord_message_id,
                       updated_by_id, updated_by_name, updated_at, last_synced_at
                FROM dashboard_event_lineups
                WHERE guild_id = %s AND event_id = %s
                """,
                (int(guild_id), str(event_id)),
            )
            row = dict(cur.fetchone() or {})
    finally:
        conn.close()
    if not row:
        return _event_lineup_default(event or {}, candidates=candidates)
    try:
        lineup = json.loads(row.get("lineup_json") or "{}")
    except Exception:
        lineup = {}
    if not isinstance(lineup, dict):
        lineup = {}
    lineup.setdefault("group_size", 6)
    lineup.setdefault("group_count", max(1, len(lineup.get("groups") or [])))
    lineup.setdefault("groups", [])
    lineup.setdefault("bench", [])
    lineup["published"] = bool(row.get("published"))
    lineup["discord_channel_id"] = int(row.get("discord_channel_id") or 0)
    lineup["discord_message_id"] = int(row.get("discord_message_id") or 0)
    lineup["updated_by_id"] = str(row.get("updated_by_id") or "")
    lineup["updated_by_name"] = str(row.get("updated_by_name") or "")
    lineup["updated_at"] = row.get("updated_at")
    lineup["last_synced_at"] = row.get("last_synced_at")
    return lineup


def _normalize_event_lineup(event: dict[str, Any], raw: Any, *, candidates: Optional[list[dict[str, Any]]] = None) -> dict[str, Any]:
    """Lineup gegen aktuelle Event-Zusagen validieren und Dubletten entfernen."""
    data = raw if isinstance(raw, dict) else {}
    candidates = list(candidates) if candidates is not None else _event_lineup_candidates(event)
    by_uid = {int(x["user_id"]): x for x in candidates}
    size = max(1, min(24, int(_num(data.get("group_size"), 6) or 6)))
    requested_count = max(1, min(20, int(_num(data.get("group_count"), 1) or 1)))
    raw_groups = data.get("groups") if isinstance(data.get("groups"), list) else []
    requested_count = max(requested_count, len(raw_groups), 1)
    groups: list[dict[str, Any]] = []
    used: set[int] = set()
    for idx in range(requested_count):
        src = raw_groups[idx] if idx < len(raw_groups) and isinstance(raw_groups[idx], dict) else {}
        name = re.sub(r"\s+", " ", str(src.get("name") or f"Gruppe {idx + 1}").strip())[:60] or f"Gruppe {idx + 1}"
        members: list[dict[str, Any]] = []
        for item in (src.get("members") or []):
            uid = _user_id(item.get("user_id") if isinstance(item, dict) else item)
            if not uid or uid in used or uid not in by_uid or len(members) >= size:
                continue
            used.add(uid)
            members.append(dict(by_uid[uid]))
        groups.append({"name": name, "members": members})
    bench: list[dict[str, Any]] = []
    for item in (data.get("bench") or []):
        uid = _user_id(item.get("user_id") if isinstance(item, dict) else item)
        if not uid or uid in used or uid not in by_uid:
            continue
        used.add(uid)
        bench.append(dict(by_uid[uid]))
    return {
        "group_size": size,
        "group_count": len(groups),
        "groups": groups,
        "bench": bench,
        "published": bool(data.get("published")),
        "candidate_count": len(candidates),
    }


def _save_event_lineup(guild_id: int, event_id: str, event: dict[str, Any], lineup: dict[str, Any], actor: dict[str, Any], *, candidates: Optional[list[dict[str, Any]]] = None) -> dict[str, Any]:
    if not _database_url():
        raise RuntimeError("DATABASE_URL fehlt.")
    clean = _normalize_event_lineup(event, lineup, candidates=candidates)
    actor_id = str(actor.get("user_id") or actor.get("id") or "")
    actor_name = str(actor.get("username") or actor.get("global_name") or actor_id or "Dashboard")
    _ensure_admin_tables()
    conn = _pg_connect()
    try:
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO dashboard_event_lineups
                    (guild_id, event_id, lineup_json, published, updated_by_id, updated_by_name, updated_at)
                VALUES (%s, %s, %s, %s, %s, %s, NOW())
                ON CONFLICT (guild_id, event_id) DO UPDATE SET
                    lineup_json = EXCLUDED.lineup_json,
                    published = EXCLUDED.published,
                    updated_by_id = EXCLUDED.updated_by_id,
                    updated_by_name = EXCLUDED.updated_by_name,
                    updated_at = NOW()
                """,
                (int(guild_id), str(event_id), json.dumps(clean, ensure_ascii=False, separators=(",", ":")), bool(clean.get("published")), actor_id, actor_name),
            )
            cur.execute(
                """
                INSERT INTO dashboard_admin_action_log
                    (guild_id, action_type, target_type, target_id, actor_id, actor_name, payload_json)
                VALUES (%s, 'event_lineup_save', 'event', %s, %s, %s, %s)
                """,
                (int(guild_id), str(event_id), actor_id, actor_name, json.dumps({"groups": clean.get("group_count"), "group_size": clean.get("group_size"), "published": clean.get("published")}, ensure_ascii=False)),
            )
        conn.commit()
    finally:
        conn.close()
    return clean


def _event_lineup_panel(data: dict[str, Any], event: dict[str, Any], event_id: str, request: Optional[Request]) -> str:
    if request is None or not _is_dashboard_admin(request):
        return ""
    guild_id = int(_safe_guild_id(data) or 0)
    snap = data.get("snapshot") or {}
    candidates = _event_lineup_candidates_for_snapshot(snap, event)
    aion_profiles = _aion2_profiles_for_users(guild_id, [int(x.get("user_id") or 0) for x in candidates]) if bool(_dashboard_module_setting_value(guild_id,'onboarding','aion2_enabled',False)) else {}
    for candidate in candidates:
        ap=aion_profiles.get(int(candidate.get("user_id") or 0)) or {}
        cls=_aion2_normalize_class(ap.get("class_name"))
        if cls:
            meta=AION2_CLASS_META.get(cls) or {}
            candidate["class_name"]=cls
            candidate["class_name_en"]=str(meta.get("en") or "")
            candidate["class_role"]=str(meta.get("role") or ap.get("main_role") or "")
            candidate["class_icon_url"]=_aion2_class_icon_url(cls)
    stored = _load_event_lineup(guild_id, str(event_id), event, candidates=candidates)
    clean = _normalize_event_lineup(event, stored, candidates=candidates)
    clean["published"] = bool(stored.get("published"))
    clean["discord_channel_id"] = int(stored.get("discord_channel_id") or 0)
    clean["discord_message_id"] = int(stored.get("discord_message_id") or 0)
    clean["updated_by_name"] = str(stored.get("updated_by_name") or "")
    clean["updated_at"] = stored.get("updated_at")
    clean["last_synced_at"] = stored.get("last_synced_at")

    payload = {
        "event_id": str(event_id),
        "group_size": clean.get("group_size", 6),
        "group_count": clean.get("group_count", 1),
        "groups": clean.get("groups") or [],
        "bench": clean.get("bench") or [],
        "published": bool(clean.get("published")),
        "candidates": candidates,
    }
    js_data = json.dumps(payload, ensure_ascii=False, separators=(",", ":")).replace("</", "<\\/")
    pub_text = "🟢 Discord-Live-Sync aktiv" if clean.get("published") else "⚪ Noch nicht auf Discord veröffentlicht"
    discord_link = ""
    if clean.get("discord_channel_id") and clean.get("discord_message_id"):
        discord_link = f'<a class="btn ghost" href="https://discord.com/channels/{int(guild_id)}/{int(clean.get("discord_channel_id"))}/{int(clean.get("discord_message_id"))}" target="_blank" rel="noopener">Discord-Aufstellung öffnen</a>'

    return f"""
    <section class="panel lineup-panel" id="lineup">
      <div class="lineup-toolbar">
        <div>
          <h2>🧩 Raid-/Gruppenaufstellung</h2>
          <p class="muted">Ziehe angemeldete Spieler per Drag & Drop in die Gruppen. Nach dem Veröffentlichen werden weitere Verschiebungen automatisch mit dem Discord-Post synchronisiert.</p>
        </div>
        <span id="lineup-sync-state" class="pill">{_e(pub_text)}</span>
      </div>
      <div class="lineup-settings">
        <label>Gruppengröße <input id="lineup-group-size" type="number" min="1" max="24" value="{int(clean.get('group_size') or 6)}"></label>
        <label>Gruppen <input id="lineup-group-count" type="number" min="1" max="20" value="{int(clean.get('group_count') or 1)}"></label>
        <button class="btn ghost" type="button" id="lineup-apply-size">Gruppen anwenden</button>
        <button class="btn ghost" type="button" id="lineup-auto">⚡ Automatisch verteilen</button>
        <button class="btn" type="button" id="lineup-publish">📣 Auf Discord veröffentlichen</button>
        {discord_link}
      </div>
      <div id="lineup-save-note" class="muted" style="margin:8px 0 14px">{_e(('Zuletzt geändert von ' + str(clean.get('updated_by_name'))) if clean.get('updated_by_name') else 'Noch keine gespeicherte Aufstellung.')}</div>
      <div class="lineup-board">
        <div class="lineup-pool-wrap">
          <h3>Angemeldet / nicht eingeteilt <span id="lineup-pool-count" class="pill"></span></h3>
          <div id="lineup-pool" class="lineup-dropzone lineup-pool" data-zone="pool"></div>
          <h3 style="margin-top:16px">Reserve / Bank</h3>
          <div id="lineup-bench" class="lineup-dropzone lineup-bench" data-zone="bench"></div>
        </div>
        <div id="lineup-groups" class="lineup-groups"></div>
      </div>
    </section>
    <style>
      .lineup-toolbar{{display:flex;justify-content:space-between;align-items:flex-start;gap:14px;flex-wrap:wrap}}.lineup-toolbar h2{{margin-top:0}}
      .lineup-settings{{display:flex;gap:10px;align-items:end;flex-wrap:wrap;margin:12px 0}}.lineup-settings label{{display:grid;gap:5px;font-size:12px;color:var(--muted)}}
      .lineup-settings input{{width:95px;padding:9px;border-radius:10px;border:1px solid rgba(255,255,255,.14);background:rgba(0,0,0,.2);color:inherit}}
      .lineup-board{{display:grid;grid-template-columns:minmax(240px,.8fr) minmax(0,2fr);gap:14px}}.lineup-pool-wrap{{border:1px solid rgba(255,255,255,.09);border-radius:16px;padding:12px;background:rgba(0,0,0,.12)}}
      .lineup-groups{{display:grid;grid-template-columns:repeat(auto-fit,minmax(245px,1fr));gap:12px}}.lineup-group{{border:1px solid rgba(214,168,79,.22);border-radius:16px;padding:12px;background:rgba(0,0,0,.15)}}
      .lineup-group-head{{display:flex;justify-content:space-between;gap:8px;align-items:center;margin-bottom:8px}}.lineup-group-name{{font-weight:800;color:#efd594;background:transparent;border:0;border-bottom:1px dashed rgba(239,213,148,.35);min-width:0;width:150px}}
      .lineup-dropzone{{min-height:64px;border:1px dashed rgba(255,255,255,.18);border-radius:12px;padding:8px;display:flex;flex-direction:column;gap:7px}}.lineup-dropzone.drag-over{{border-color:#efd594;background:rgba(214,168,79,.08)}}
      .lineup-player{{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:9px 10px;border-radius:11px;background:rgba(255,255,255,.055);border:1px solid rgba(255,255,255,.08);cursor:grab;user-select:none}}.lineup-player:active{{cursor:grabbing}}.lineup-player.selected{{outline:2px solid #efd594;background:rgba(214,168,79,.16)}}.lineup-player b{{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}}.lineup-player-main{{display:flex;align-items:center;gap:8px;min-width:0}}.lineup-player-meta{{display:flex;align-items:center;gap:5px;flex-wrap:wrap;justify-content:flex-end}}.lineup-class-icon{{width:36px;height:36px;object-fit:contain;flex:0 0 36px;filter:drop-shadow(0 0 4px rgba(0,0,0,.65))}}.lineup-role{{font-size:11px;padding:3px 6px;border-radius:999px;white-space:nowrap;background:rgba(214,168,79,.11);color:#e8cf99}}.lineup-pool .lineup-player{{background:rgba(255,255,255,.035)}}
      @media(max-width:850px){{.lineup-board{{grid-template-columns:1fr}}.lineup-groups{{grid-template-columns:1fr}}}}
    </style>
    <script>
    (()=>{{
      const initial={js_data};
      const byId=new Map((initial.candidates||[]).map(x=>[String(x.user_id),x]));
      let state={{group_size:Number(initial.group_size||6),group_count:Number(initial.group_count||1),groups:structuredClone(initial.groups||[]),bench:structuredClone(initial.bench||[]),published:!!initial.published}};
      let timer=null, saving=false, saveAgain=false, revision=0, dragUid='', selectedUid='';
      const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}}[c]));
      function normalize(){{
        state.group_size=Math.max(1,Math.min(24,Number(state.group_size||6)));
        state.group_count=Math.max(1,Math.min(20,Number(state.group_count||1)));
        while(state.groups.length<state.group_count) state.groups.push({{name:`Gruppe ${{state.groups.length+1}}`,members:[]}});
        if(state.groups.length>state.group_count){{const removed=state.groups.splice(state.group_count);for(const g of removed) state.bench.push(...(g.members||[]));}}
        state.groups.forEach((g,i)=>{{g.name=g.name||`Gruppe ${{i+1}}`;g.members=(g.members||[]).slice(0,state.group_size)}});
      }}
      function placedIds(){{const x=new Set();state.groups.forEach(g=>(g.members||[]).forEach(m=>x.add(String(m.user_id))));(state.bench||[]).forEach(m=>x.add(String(m.user_id)));return x}}
      function playerHtml(p){{const sel=String(p.user_id)===selectedUid?' selected':'';const cls=String(p.class_name||'');const en=String(p.class_name_en||'');const iconUrl=String(p.class_icon_url||'');const title=cls+(en?` (${{en}})`:``);const iconHtml=cls&&iconUrl?`<img class="lineup-class-icon" src="${{esc(iconUrl)}}" alt="${{esc(cls)}}" title="${{esc(title)}}">`:'';return `<div class="lineup-player${{sel}}" draggable="true" tabindex="0" data-user-id="${{esc(p.user_id)}}"><span class="lineup-player-main">${{iconHtml}}<b>${{esc(p.display_name)}}</b></span><span class="lineup-player-meta"><span class="lineup-role">${{esc(p.role||p.class_role||'')}}</span></span></div>`}}
      function render(){{
        normalize();
        const used=placedIds();
        const pool=(initial.candidates||[]).filter(p=>!used.has(String(p.user_id)));
        document.getElementById('lineup-pool').innerHTML=pool.map(playerHtml).join('')||'<span class="muted">Alle eingeteilt.</span>';
        document.getElementById('lineup-pool-count').textContent=pool.length;
        document.getElementById('lineup-bench').innerHTML=(state.bench||[]).map(playerHtml).join('')||'<span class="muted">Keine Reserve.</span>';
        document.getElementById('lineup-groups').innerHTML=state.groups.map((g,i)=>`<div class="lineup-group"><div class="lineup-group-head"><input class="lineup-group-name" data-gi="${{i}}" value="${{esc(g.name)}}"><span class="pill">${{(g.members||[]).length}} / ${{state.group_size}}</span></div><div class="lineup-dropzone" data-zone="group" data-gi="${{i}}">${{(g.members||[]).map(playerHtml).join('')||'<span class="muted">Spieler hierher ziehen</span>'}}</div></div>`).join('');
        bindDnD();
        document.querySelectorAll('.lineup-group-name').forEach(el=>el.addEventListener('change',()=>{{state.groups[Number(el.dataset.gi)].name=el.value.trim()||`Gruppe ${{Number(el.dataset.gi)+1}}`;markDirty()}}));
      }}
      function removeUser(uid){{state.groups.forEach(g=>g.members=(g.members||[]).filter(m=>String(m.user_id)!==uid));state.bench=(state.bench||[]).filter(m=>String(m.user_id)!==uid)}}
      function move(uid,zone,gi){{
        const p=byId.get(String(uid));if(!p)return false;
        if(zone==='group'){{const g=state.groups[gi];if(!g)return false;const already=(g.members||[]).some(m=>String(m.user_id)===String(uid));if(!already && g.members.length>=state.group_size){{document.getElementById('lineup-save-note').textContent=`❌ ${{g.name}} ist bereits voll.`;return false;}}}}
        removeUser(String(uid));
        if(zone==='bench') state.bench.push(p);
        else if(zone==='group') state.groups[gi].members.push(p);
        selectedUid='';
        render();markDirty();return true;
      }}
      function bindDnD(){{
        document.querySelectorAll('.lineup-player').forEach(el=>{{
          el.addEventListener('dragstart',e=>{{dragUid=el.dataset.userId||'';try{{e.dataTransfer.setData('text/plain',dragUid);e.dataTransfer.effectAllowed='move'}}catch(_e){{}}}});
          el.addEventListener('dragend',()=>{{dragUid='';document.querySelectorAll('.lineup-dropzone').forEach(z=>z.classList.remove('drag-over'))}});
          el.addEventListener('click',e=>{{e.stopPropagation();selectedUid=(selectedUid===el.dataset.userId?'':el.dataset.userId);document.querySelectorAll('.lineup-player').forEach(x=>x.classList.toggle('selected',x.dataset.userId===selectedUid))}});
          el.addEventListener('keydown',e=>{{if(e.key==='Enter'||e.key===' '){{e.preventDefault();el.click()}}}});
        }});
        document.querySelectorAll('.lineup-dropzone').forEach(z=>{{
          z.addEventListener('dragenter',e=>{{e.preventDefault();z.classList.add('drag-over')}});
          z.addEventListener('dragover',e=>{{e.preventDefault();if(e.dataTransfer)e.dataTransfer.dropEffect='move';z.classList.add('drag-over')}});
          z.addEventListener('dragleave',e=>{{if(!z.contains(e.relatedTarget))z.classList.remove('drag-over')}});
          z.addEventListener('drop',e=>{{e.preventDefault();e.stopPropagation();z.classList.remove('drag-over');let uid=dragUid;try{{uid=uid||e.dataTransfer.getData('text/plain')}}catch(_e){{}};dragUid='';if(!uid)return;if(z.dataset.zone==='pool'){{removeUser(String(uid));selectedUid='';render();markDirty()}}else move(String(uid),z.dataset.zone,Number(z.dataset.gi||0))}});
          z.addEventListener('click',()=>{{if(!selectedUid)return;if(z.dataset.zone==='pool'){{removeUser(selectedUid);selectedUid='';render();markDirty()}}else move(selectedUid,z.dataset.zone,Number(z.dataset.gi||0))}});
        }});
      }}
      function payloadState(){{
        normalize();
        return {{
          group_size:state.group_size,group_count:state.group_count,published:!!state.published,
          groups:state.groups.map(g=>({{name:g.name,members:(g.members||[]).map(m=>({{user_id:String(m.user_id)}}))}})),
          bench:(state.bench||[]).map(m=>({{user_id:String(m.user_id)}}))
        }};
      }}
      function layoutSignature(obj){{
        const groups=(obj.groups||[]).map(g=>({{name:String(g.name||''),members:(g.members||[]).map(m=>String(m.user_id??m))}}));
        const bench=(obj.bench||[]).map(m=>String(m.user_id??m));
        return JSON.stringify({{group_size:Number(obj.group_size||6),group_count:Number(obj.group_count||groups.length||1),groups,bench}});
      }}
      function assignedIds(obj){{const ids=[];(obj.groups||[]).forEach(g=>(g.members||[]).forEach(m=>ids.push(String(m.user_id??m))));(obj.bench||[]).forEach(m=>ids.push(String(m.user_id??m)));return ids.sort().join(',')}}
      function markDirty(){{revision++;scheduleSave()}}
      async function save(publishOverride=null){{
        if(publishOverride!==null){{state.published=!!publishOverride;revision++;}}
        if(saving){{saveAgain=true;return;}}
        saving=true;saveAgain=false;
        const requestRevision=revision;
        const sent=payloadState();
        const note=document.getElementById('lineup-save-note');note.textContent='Speichere…';
        try{{
          const res=await fetch(`/event/${{encodeURIComponent(initial.event_id)}}/lineup`,{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify(sent)}});
          const data=await res.json();if(!res.ok||!data.ok)throw new Error(data.error||`HTTP ${{res.status}}`);
          const server=data.lineup||{{}};
          if(layoutSignature(server)!==layoutSignature(sent))throw new Error('Die gespeicherte Aufstellung stimmt nicht mit deiner Verschiebung überein. Deine lokale Position bleibt sichtbar; bitte prüfe die Fehlermeldung oder lade einmal neu.');
          state.published=!!server.published;
          document.getElementById('lineup-sync-state').textContent=state.published?'🟢 Discord-Live-Sync aktiv':'⚪ Noch nicht auf Discord veröffentlicht';
          const n=assignedIds(sent)?assignedIds(sent).split(',').filter(Boolean).length:0;
          note.textContent=(data.message||'✅ Aufstellung gespeichert.')+` · ${{n}} eingeteilt`;
        }}catch(err){{note.textContent='❌ '+err.message}}
        finally{{saving=false;if(saveAgain||revision>requestRevision){{saveAgain=false;clearTimeout(timer);timer=setTimeout(()=>save(null),80)}}}}
      }}
      function scheduleSave(){{clearTimeout(timer);timer=setTimeout(()=>save(null),300)}}
      document.getElementById('lineup-apply-size').addEventListener('click',()=>{{state.group_size=Number(document.getElementById('lineup-group-size').value||6);state.group_count=Number(document.getElementById('lineup-group-count').value||1);render();markDirty()}});
      document.getElementById('lineup-publish').addEventListener('click',()=>save(true));
      document.getElementById('lineup-auto').addEventListener('click',()=>{{
        state.group_size=Number(document.getElementById('lineup-group-size').value||6);state.group_count=Number(document.getElementById('lineup-group-count').value||1);normalize();state.groups.forEach(g=>g.members=[]);state.bench=[];
        const buckets={{Tank:[],Support:[],DPS:[],Reserve:[],Other:[]}};(initial.candidates||[]).forEach(p=>(buckets[p.role]||buckets.Other).push(p));
        for(const key of Object.keys(buckets)) buckets[key].sort((a,b)=>String(a.display_name).localeCompare(String(b.display_name)));
        const order=[...buckets.Tank,...buckets.Support,...buckets.DPS,...buckets.Other,...buckets.Reserve];
        let cursor=0;for(const p of order){{let placed=false;for(let tries=0;tries<state.groups.length;tries++){{const gi=cursor%state.groups.length;cursor++;if(state.groups[gi].members.length<state.group_size){{state.groups[gi].members.push(p);placed=true;break}}}}if(!placed)state.bench.push(p)}}
        render();markDirty();
      }});
      render();
    }})();
    </script>
    """

def _event_status_text(ev: dict[str, Any]) -> str:
    if ev.get("_attendance_review_only"):
        return "Review offen"
    if ev.get("_pending_ec_check"):
        return "EC offen"
    if _is_running_event(ev):
        return "läuft/offen"
    return str(ev.get("status") or ev.get("state") or "geplant")


def _event_role_counts(ev: dict[str, Any]) -> str:
    yes = ev.get("yes") if isinstance(ev.get("yes"), dict) else {}
    if yes:
        return " · ".join(f"{k}: {len(v) if isinstance(v, list) else 0}" for k, v in yes.items()) or "—"
    return f"Teilnehmer: {ev.get('participant_count', ev.get('participants', '—'))}"



def _dashboard_select_options_from_settings(snap: dict[str, Any], kind: str) -> list[tuple[str, str]]:
    settings = snap.get("settings") if isinstance(snap.get("settings"), dict) else {}
    rows = settings.get(kind) if isinstance(settings.get(kind), list) else []
    out: list[tuple[str, str]] = []
    seen: set[str] = set()
    id_key = "channel_id" if kind == "channels" else "role_id"
    for row in rows:
        if not isinstance(row, dict):
            continue
        value = str(row.get(id_key) or row.get("id") or row.get("value") or "").strip()
        if not value or value in seen:
            continue
        seen.add(value)
        name = str(row.get("name") or row.get("label") or row.get("key") or value).strip()
        out.append((value, name))
    return out


def _dashboard_channel_select_html(snap: dict[str, Any], *, required: bool = True, selected: Any = "", name: str = "channel_id") -> str:
    # Event-Zielkanäle kommen primär aus dem echten Discord-Katalog des aktuellen
    # Guild-Snapshots. Die alte settings.channels-Liste enthält zusätzlich
    # historische Config-Schlüssel und war deshalb unvollständig/verschmutzt.
    guild = snap.get("guild") if isinstance(snap.get("guild"), dict) else {}
    catalog = guild.get("discord_catalog") if isinstance(guild.get("discord_catalog"), dict) else {}
    catalog_rows = [row for row in (catalog.get("channels") or []) if isinstance(row, dict)]
    text_rows = [row for row in catalog_rows if str(row.get("kind") or "").lower() == "text"]
    text_rows.sort(key=lambda row: (int(_num(row.get("position"), 0)), str(row.get("name") or "").casefold()))
    opts: list[tuple[str, str]] = []
    seen: set[str] = set()
    for row in text_rows:
        value = str(row.get("id") or "").strip()
        if not value or value in seen:
            continue
        seen.add(value)
        opts.append((value, str(row.get("name") or value).strip()))
    if not opts:
        opts = _dashboard_select_options_from_settings(snap, "channels")
    req = " required" if required else ""
    selected_s = str(selected or "").strip()
    if selected_s and selected_s not in {value for value, _ in opts}:
        opts.insert(0, (selected_s, f"Gespeicherter Kanal {selected_s}"))
    if not opts:
        value = f' value="{_e(selected_s)}"' if selected_s else ""
        return f'<input name="{_e(name)}"{req}{value} placeholder="Kanal-ID, falls keine Kanäle im Snapshot sind">'
    html_value = f'<select name="{_e(name)}"{req}><option value="">Kanal auswählen</option>'
    for value, label in opts:
        sel = " selected" if value == selected_s else ""
        html_value += f'<option value="{_e(value)}"{sel}>#{_e(label)} · {_e(value)}</option>'
    html_value += '</select>'
    return html_value

def _dashboard_role_select_html(snap: dict[str, Any], *, selected: Any = "", name: str = "target_role_id") -> str:
    guild = snap.get("guild") if isinstance(snap.get("guild"), dict) else {}
    catalog = guild.get("discord_catalog") if isinstance(guild.get("discord_catalog"), dict) else {}
    role_rows = [row for row in (catalog.get("roles") or []) if isinstance(row, dict)]
    role_rows.sort(key=lambda row: (-int(_num(row.get("position"), 0)), str(row.get("name") or "").casefold()))
    opts: list[tuple[str, str]] = []
    seen: set[str] = set()
    for row in role_rows:
        value = str(row.get("id") or "").strip()
        if not value or value in seen:
            continue
        seen.add(value)
        opts.append((value, str(row.get("name") or value).strip()))
    if not opts:
        opts = _dashboard_select_options_from_settings(snap, "roles")
    selected_s = str(selected or "").strip()
    if selected_s and selected_s not in {value for value, _ in opts}:
        opts.insert(0, (selected_s, f"Gespeicherte Rolle {selected_s}"))
    if not opts:
        value = f' value="{_e(selected_s)}"' if selected_s else ""
        return f'<input name="{_e(name)}"{value} placeholder="optional: Rollen-ID, falls keine Rollen im Snapshot sind">'
    html_value = f'<select name="{_e(name)}"><option value="">Keine Zielrolle / alle erlaubten Mitglieder</option>'
    for value, label in opts:
        sel = " selected" if value == selected_s else ""
        html_value += f'<option value="{_e(value)}"{sel}>@{_e(label)} · {_e(value)}</option>'
    html_value += '</select>'
    return html_value


_EVENT_VISIBLE_TYPES: tuple[str, ...] = (
    "Normal Mode Raid",
    "Hardmode Raid",
    "Dimensionsprüfung",
    "Gildenbosse",
    "Segensstein",
    "Benutzerdefiniertes Event",
)

_EVENT_DKP_TYPES: tuple[str, ...] = (
    "Nicht DKP-relevant",
    "Gildenboss",
    "NM Raid",
    "HM Raid",
    "Übungsrun HM Raid",
    "Übungsrun Trials",
    "Segensstein PvP",
)

_EVENT_IMAGE_CHOICES: tuple[tuple[str, str], ...] = (
    ("auto", "Standardbild des Eventtyps"),
    ("boss", "Gildenbosse"),
    ("normal", "Normal Mode Raid"),
    ("hard", "Hardmode Raid"),
    ("trials", "Dimensionsprüfung"),
    ("pvp", "Segensstein"),
    ("custom", "Eigene Bild-URL"),
    ("none", "Kein Bild"),
)


def _dashboard_select_html(name: str, values: tuple[str, ...], selected: Any = "", *, blank_label: str = "") -> str:
    selected_s = str(selected or "").strip()
    out = [f'<select name="{_e(name)}">']
    if blank_label:
        out.append(f'<option value="">{_e(blank_label)}</option>')
    for value in values:
        sel = " selected" if value == selected_s else ""
        out.append(f'<option value="{_e(value)}"{sel}>{_e(value)}</option>')
    out.append('</select>')
    return "".join(out)


def _dashboard_event_type_select_html(selected: Any = "", *, name: str = "dkp_event_type") -> str:
    return _dashboard_select_html(name, _EVENT_DKP_TYPES, selected)


def _dashboard_visible_event_type_select_html(selected: Any = "", *, name: str = "event_type") -> str:
    return _dashboard_select_html(name, _EVENT_VISIBLE_TYPES, selected, blank_label="Eventtyp auswählen")


def _dashboard_image_type_select_html(selected: Any = "auto", *, name: str = "image_type", element_id: str = "event-image-type") -> str:
    selected_s = str(selected or "auto").strip().lower()
    options = []
    for value, label in _EVENT_IMAGE_CHOICES:
        sel = " selected" if value == selected_s else ""
        options.append(f'<option value="{_e(value)}"{sel}>{_e(label)}</option>')
    return f'<select id="{_e(element_id)}" name="{_e(name)}">{"".join(options)}</select>'


def _event_admin_id(ev: dict[str, Any]) -> str:
    return str(ev.get("event_id") or ev.get("id") or ev.get("message_id") or "").strip()


def _event_admin_title(ev: dict[str, Any]) -> str:
    return str(ev.get("title") or ev.get("name") or _event_admin_id(ev) or "Event").strip()


def _event_admin_datetime(ev: dict[str, Any]) -> Optional[datetime]:
    return _event_dt_obj(ev.get("when_iso") or ev.get("start_at") or ev.get("created_at"))


def _event_admin_input_date_time(ev: dict[str, Any]) -> tuple[str, str]:
    dt = _event_admin_datetime(ev)
    if not dt:
        return "", ""
    try:
        local = dt.astimezone(BERLIN_TZ)
    except Exception:
        local = dt
    return local.strftime("%Y-%m-%d"), local.strftime("%H:%M")


def _event_admin_image_mode(ev: dict[str, Any]) -> str:
    explicit = str(ev.get("image_type") or ev.get("image_preset") or "").strip().lower()
    aliases = {
        "guild_boss": "boss", "gildenboss": "boss", "gildenbosse": "boss",
        "normal_raid": "normal", "normal mode raid": "normal", "nm raid": "normal",
        "hard_raid": "hard", "hardmode raid": "hard", "hm raid": "hard",
        "dimensionsprüfung": "trials", "dimensionspruefung": "trials", "trial": "trials",
        "segensstein": "pvp", "segensstein pvp": "pvp",
    }
    if explicit in {x[0] for x in _EVENT_IMAGE_CHOICES}:
        return explicit
    if explicit in aliases:
        return aliases[explicit]
    raw = _event_image_raw_url(ev)
    for marker, preset in _EVENT_IMAGE_LEGACY_MARKERS.items():
        if marker in raw:
            return {"guild_boss": "boss", "normal_raid": "normal", "hard_raid": "hard", "trials": "trials", "pvp": "pvp"}.get(preset, "auto")
    if raw:
        return "custom"
    return "auto"


def _event_admin_discord_url(ev: dict[str, Any]) -> str:
    for key in ("jump_url", "message_url", "discord_url", "post_url"):
        value = str(ev.get(key) or "").strip()
        if value.startswith("https://"):
            return value
    guild_id = str(ev.get("guild_id") or "").strip()
    channel_id = str(ev.get("channel_id") or "").strip()
    message_id = str(ev.get("message_id") or ev.get("event_id") or ev.get("id") or "").strip()
    if guild_id.isdigit() and channel_id.isdigit() and message_id.isdigit():
        return f"https://discord.com/channels/{guild_id}/{channel_id}/{message_id}"
    return ""


def _event_admin_find(data: dict[str, Any], event_id: str) -> dict[str, Any]:
    snap = data.get("snapshot") or {}
    wanted = str(event_id or "").strip()
    for ev in _events_items(snap):
        if _event_admin_id(ev) == wanted:
            return dict(ev)
    for ev in _events_with_pending_ec_checks(snap):
        if _event_admin_id(ev) == wanted:
            return dict(ev)
    guild_id = _safe_guild_id(data)
    if guild_id:
        for ev in _open_attendance_review_events_for_homepage(snap, guild_id, limit=120):
            if _event_admin_id(ev) == wanted:
                return dict(ev)
    return {}


def _event_admin_image_preview(ev: dict[str, Any], *, css_class: str = "admin-event-thumb") -> str:
    url = _dashboard_event_image_url(ev)
    if not url:
        return f'<div class="{_e(css_class)} admin-event-thumb-empty"><span>⚔️</span><small>Kein Bild</small></div>'
    return (
        f'<div class="{_e(css_class)}">'
        f'<img src="{_e(url)}" alt="{_e(_event_admin_title(ev))}" loading="lazy" '
        'onerror="this.style.display=\'none\';this.nextElementSibling.style.display=\'flex\'">'
        '<div class="admin-event-image-error" style="display:none"><span>⚠️</span><small>Bild nicht erreichbar</small></div>'
        '</div>'
    )


def _event_admin_queue_state(action_rows: list[dict[str, Any]], event_id: str) -> tuple[str, str]:
    for row in action_rows:
        if str(row.get("event_id") or "") != str(event_id):
            continue
        status = str(row.get("status") or "").lower()
        if status in {"pending", "processing"}:
            return ("Änderung wartet" if status == "pending" else "Bot verarbeitet", "warn")
        if status in {"failed", "rejected"}:
            return ("Änderung fehlgeschlagen", "danger")
        if status == "done":
            return ("Synchronisiert", "ok")
    return ("Synchron", "ok")


def _render_event_editor(data: dict[str, Any], event_id: str, current_user: Optional[dict[str, Any]] = None, msg: str = "", request: Optional[Request] = None) -> str:
    if not data.get("ok"):
        return _html_shell("Event bearbeiten · Beer and Buffs Dashboard", f"<section class='panel'><h1>Event bearbeiten</h1><p>{_e(data.get('error'))}</p></section>", nav_mode="admin")
    ev = _event_admin_find(data, event_id)
    if not ev:
        return _html_shell("Event nicht gefunden · Beer and Buffs Dashboard", "<section class='panel'><h1>❌ Event nicht gefunden</h1><p class='muted'>Der Eventdatensatz ist im aktuellen Snapshot nicht vorhanden.</p><a class='btn' href='/events-admin'>Zur Eventverwaltung</a></section>", nav_mode="admin")
    snap = data.get("snapshot") or {}
    guild_id = _safe_guild_id(data)
    eid = _event_admin_id(ev)
    title = _event_admin_title(ev)
    date_value, time_value = _event_admin_input_date_time(ev)
    visible_type = str(ev.get("event_type") or "").strip()
    dkp_type = str(ev.get("dkp_event_type") or "").strip() or "Nicht DKP-relevant"
    description = str(ev.get("description") or "")
    image_mode = _event_admin_image_mode(ev)
