@app.post("/event/{event_id}/rsvp")
async def event_dashboard_rsvp(event_id: str, request: Request, _: bool = Depends(_auth)):
    data = _snapshot_payload()
    guild_id = int(_safe_guild_id(data) or 0)
    snap = data.get("snapshot") or {}
    uid = int(_current_user_id(request) or 0)
    actor = _current_user(request) or {}
    form = _parse_urlencoded_body(await request.body())
    choice = normalize_event_role(form.get("choice") or "")
    next_path = str(form.get("next") or f"/event/{event_id}").strip()
    allowed_next = {f"/event/{event_id}", "/member/events", "/events"}
    if next_path not in allowed_next:
        next_path = f"/event/{event_id}"

    if not uid:
        message = "❌ Für Event-Rückmeldungen musst du mit Discord eingeloggt sein."
    elif not guild_id:
        message = "❌ Guild-ID fehlt."
    elif normalize_event_role(choice) not in {"TANK", "SUPPORT", "DPS", "BANK", "MAYBE", "NO"}:
        message = "❌ Ungültige Rückmeldung."
    else:
        event = _event_by_id(snap, str(event_id))
        if not event:
            message = "❌ Event wurde nicht gefunden."
        elif not _event_rsvp_is_open(event):
            message = "❌ Dieses Event ist für Rückmeldungen geschlossen."
        else:
            actor = dict(actor)
            actor["user_id"] = str(uid)
            payload = {"event_id": str(event_id), "choice": choice, "source": "dashboard_member_rsvp"}
            result = _enqueue_event_action_request(guild_id, "rsvp", payload, actor)
            label = {"TANK":"Tank", "SUPPORT":"Support", "HEAL":"Support", "HEALER":"Support", "DPS":"DPS", "BANK":"Reserve", "MAYBE":"Vielleicht", "NO":"Abgemeldet"}.get(choice, choice)
            message = (f"✅ {label} wurde an den Bot gesendet. Discord und Dashboard werden synchronisiert." if result.get("ok") else f"❌ {result.get('error') or 'Rückmeldung konnte nicht gesendet werden.'}")

    joiner = "&" if "?" in next_path else "?"
    return RedirectResponse(next_path + joiner + "msg=" + urllib.parse.quote(message), status_code=303)



@app.post("/event/{event_id}/lineup")
async def event_lineup_save(event_id: str, request: Request, _: bool = Depends(_admin_auth)):
    data = _snapshot_payload()
    guild_id = int(_safe_guild_id(data) or 0)
    snap = data.get("snapshot") or {}
    event = _event_by_id(snap, str(event_id))
    if not guild_id:
        return JSONResponse({"ok": False, "error": "Guild-ID fehlt."}, status_code=400)
    if not event:
        return JSONResponse({"ok": False, "error": "Event nicht gefunden."}, status_code=404)
    try:
        raw = await request.json()
    except Exception:
        return JSONResponse({"ok": False, "error": "Ungültige JSON-Daten."}, status_code=400)
    if not isinstance(raw, dict):
        return JSONResponse({"ok": False, "error": "Ungültige Aufstellung."}, status_code=400)
    actor = _current_user(request) or {"user_id": "basic-admin", "username": "Basic Admin"}
    try:
        candidates = _event_lineup_candidates_for_snapshot(snap, event)
        lineup = _save_event_lineup(guild_id, str(event_id), event, raw, actor, candidates=candidates)
    except Exception as exc:
        return JSONResponse({"ok": False, "error": f"Speichern fehlgeschlagen: {type(exc).__name__}: {exc}"}, status_code=500)

    queued = None
    if bool(lineup.get("published")):
        payload = {"event_id": str(event_id), "lineup": lineup, "publish": True, "source": "dashboard_lineup"}
        queued = _enqueue_event_action_request(guild_id, "lineup", payload, actor)
        if not queued.get("ok"):
            return JSONResponse({"ok": False, "error": queued.get("error") or "Discord-Sync konnte nicht eingeplant werden.", "lineup": lineup}, status_code=500)
    message = "✅ Aufstellung gespeichert." + (" Discord-Sync läuft…" if bool(lineup.get("published")) else "")
    return JSONResponse({"ok": True, "lineup": lineup, "message": message, "queued": queued})

