@app.post("/portal/member/{user_id}/profile-update")
async def portal_profile_update(user_id: int, request: Request, _: bool = Depends(_auth)):
    if not _portal_can_view(request, int(user_id)):
        raise HTTPException(status_code=403, detail="Keine Berechtigung für dieses Profil.")
    data = _snapshot_payload()
    guild_id = _safe_guild_id(data)
    if not guild_id:
        raise HTTPException(status_code=400, detail="Guild-ID fehlt.")
    form = _parse_urlencoded_body(await request.body())
    class_name = re.sub(r"\s+", " ", str(form.get("class_name") or "").strip())[:80]
    main_role = re.sub(r"\s+", " ", str(form.get("main_role") or "").strip())[:50]
    gearscore_raw = re.sub(r"[^0-9]", "", str(form.get("gearscore") or ""))
    gearscore = int(gearscore_raw or 0)
    if not class_name:
        raise HTTPException(status_code=400, detail="Klasse fehlt.")
    if not main_role:
        raise HTTPException(status_code=400, detail="Rolle fehlt.")
    if gearscore <= 0 or gearscore > 99999:
        raise HTTPException(status_code=400, detail="Gearscore muss zwischen 1 und 99999 liegen.")
    actor = _current_user(request) or {"user_id": "basic-admin", "username": "Basic Admin"}
    request_id = _create_profile_update_request(
        int(guild_id), int(user_id),
        class_name=class_name,
        main_role=main_role,
        gearscore=gearscore,
        actor=actor,
    )
    params = urllib.parse.urlencode({"msg": f"Profiländerung an den Bot gesendet: {request_id}"})
    return RedirectResponse(url=f"/portal/member/{int(user_id)}?{params}", status_code=303)


@app.post("/portal/member/{user_id}/aion2-update")
async def portal_aion2_update(user_id: int, request: Request, _: bool = Depends(_auth)):
    current_uid = int(_current_user_id(request) or 0)
    if current_uid != int(user_id) and not _is_portal_admin(request): raise HTTPException(status_code=403, detail="Keine Berechtigung für dieses Aion-2-Profil.")
    data = _snapshot_payload(); guild_id = int(_safe_guild_id(data) or 0)
    if not guild_id: raise HTTPException(status_code=400, detail="Guild-ID fehlt.")
    if not bool(_dashboard_module_setting_value(guild_id, 'onboarding', 'aion2_enabled', False)): raise HTTPException(status_code=404, detail="Aion-2-Komponente ist nicht aktiv.")
    form = _parse_urlencoded_body(await request.body())
    character_name = re.sub(r"\s+", " ", str(form.get("character_name") or "").strip())[:120]
    faction = _aion2_normalize_faction(form.get("faction")); class_name = _aion2_normalize_class(form.get("class_name")); main_role = _aion2_role_for_class(class_name)
    gearscore = re.sub(r"\s+", " ", str(form.get("gearscore") or "").strip())[:40]
    raw_level = re.sub(r"[^0-9]", "", str(form.get("level") or "")); level = int(raw_level) if raw_level else None
    if level is not None and not (1 <= level <= 999): raise HTTPException(status_code=400, detail="Level muss zwischen 1 und 999 liegen.")
    _ensure_v211_tables(); conn = _pg_connect()
    try:
        with conn.cursor() as cur:
            cur.execute('''INSERT INTO aion2_profiles(guild_id,user_id,character_name,class_name,main_role,faction,level,gearscore,updated_at) VALUES(%s,%s,%s,%s,%s,%s,%s,%s,%s) ON CONFLICT(guild_id,user_id) DO UPDATE SET character_name=EXCLUDED.character_name,class_name=EXCLUDED.class_name,main_role=EXCLUDED.main_role,faction=EXCLUDED.faction,level=EXCLUDED.level,gearscore=EXCLUDED.gearscore,updated_at=EXCLUDED.updated_at''',(guild_id,int(user_id),character_name,class_name,main_role,faction,level,gearscore,datetime.now(timezone.utc).isoformat()))
        conn.commit()
    finally: conn.close()
    target = "/portal" if current_uid == int(user_id) else f"/portal/member/{int(user_id)}"; params = urllib.parse.urlencode({"msg":"Aion-2-Profil gespeichert."})
    return RedirectResponse(url=f"{target}?{params}#aion2", status_code=303)


@app.post("/portal/member/{user_id}/need-change")
async def portal_need_change(user_id: int, request: Request, _: bool = Depends(_auth)):
    if not _portal_can_view(request, int(user_id)):
        raise HTTPException(status_code=403, detail="Keine Berechtigung für diese Needliste.")
    data = _snapshot_payload()
    guild_id = _safe_guild_id(data)
    if not guild_id:
        raise HTTPException(status_code=400, detail="Guild-ID fehlt.")
    form = _parse_urlencoded_body(await request.body())
    action_type = str(form.get("action_type") or "set").strip().lower()
    if action_type not in {"set", "clear"}:
        action_type = "set"
    tab = str(form.get("tab") or "Main").strip()
    slot = str(form.get("slot") or "").strip()
    if slot == "Fähigkeitskern":
        slot = "Fähigkeitskern 1"
    item_text = str(form.get("item_text") or "").strip()
    weapon_type = str(form.get("weapon_type") or "").strip()
    if tab not in {"Main", "Secondary"}:
        tab = "Main"
    valid_slots = {"Waffe 1","Waffe 2","Fähigkeitskern 1","Fähigkeitskern 2","Helm","Brust","Hose","Handschuhe","Schuhe","Brosche","Ohrringe","Kette","Armband","Ring 1","Ring 2","Gürtel","Umhang"}
    if slot not in valid_slots:
        raise HTTPException(status_code=400, detail="Ungültiger Slot.")
    if action_type == "set" and not item_text:
        raise HTTPException(status_code=400, detail="Itemname fehlt.")
    if action_type == "set":
        snap = data.get("snapshot") or {}
        catalog_items = _loot_catalog_items(snap, limit=4000)
        selected_item = next((it for it in catalog_items if _loot_key(it.get("name")) == _loot_key(item_text)), None)
        if not selected_item:
            raise HTTPException(status_code=400, detail="Das ausgewählte Item ist nicht in der Item-Datenbank vorhanden.")
        if not _need_item_slot_matches(selected_item.get("slot", ""), slot, selected_item.get("name", "")):
            raise HTTPException(status_code=400, detail=f"Das Item passt nicht in den Slot {slot}.")
        if slot.startswith("Waffe") and weapon_type:
            detected_weapon_type = _weapon_type_from_text(selected_item.get("name") or "")
            if detected_weapon_type and detected_weapon_type != weapon_type:
                raise HTTPException(status_code=400, detail="Die ausgewählte Waffe passt nicht zur gewählten Waffenart.")
    actor = _current_user(request) or {"user_id": "basic-admin", "username": "Basic Admin"}
    payload = {
        "target_user_id": int(user_id),
        "tab": tab,
        "slot": slot,
        "item_text": item_text,
        "weapon_type": weapon_type if slot.startswith("Waffe") else "",
        "source": "dashboard_portal",
        "admin_override": bool(_is_portal_admin(request) and _current_user_id(request) != int(user_id)),
    }
    rid = _create_need_change_request(guild_id, int(user_id), action_type, payload, actor)
    msg = urllib.parse.quote(f"Need-Änderung angelegt: {rid}")
    return RedirectResponse(url=f"/portal/member/{int(user_id)}?profile_tab=needlist&need_area={tab.lower()}&msg={msg}#needlist", status_code=303)


